#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN 2

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *line;

// Global variable for the gpiod chip
struct gpiod_chip *chip;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release the GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register the signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "my_app";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set the GPIO pin to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO value");
            break; // Exit the loop on error
        }

        // Print the state to standard output
        printf("GPIO %d: HIGH\n", GPIO_PIN);

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);

        // Set the GPIO pin to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO value");
            break; // Exit the loop on error
        }

        // Print the state to standard output
        printf("GPIO %d: LOW\n", GPIO_PIN);

        // Wait for 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define GPIO_LINE "gpio:2:line"
#define GPIO_VALUE "gpio:2:value"
#define GPIO_CHARGE "gpio:2:charge"
#define GPIO_DISCHARGE "gpio:2:discharge"
#define GPIO_LINE_EVENT "gpio:2:line:events"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main()
{
    struct gpiod_line_event *event;
    struct timespec ts;
    char timestamp[30];
    int state;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get line object
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input
    if (gpiod_line_request_input(line, "digital_output") < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %s for input\n", GPIO_LINE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Read GPIO value
        state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Error: Could not read GPIO value\n");
            break;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

        // Print state and timestamp
        printf("%s: GPIO %d: %d\n", timestamp, GPIO_PIN, state);

        // Consume the interrupt by reading the line
        if (gpiod_line_get_value(line) < 0) {
            fprintf(stderr, "Error: Could not read GPIO value to consume interrupt\n");
            break;
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Digital output control stopped.\n");

    return 0;
}

