// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080  // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000 // Disable comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADS1115 register
int ads1115_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an ADS1115 register
int ads1115_read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read the 16-bit ADC value from the ADS1115
int16_t ads1115_read_adc(int fd) {
    uint8_t config_reg = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_QUE_DISABLE | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;
    uint8_t read_reg = ADS1115_REG_CONVERT;

    // Write the configuration register
    if (ads1115_write_register(fd, ADS1115_REG_CONFIG, config_reg) != 0) {
        fprintf(stderr, "Failed to write configuration register.\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    uint8_t conversion_data[2];
    if (ads1115_write_register(fd, ADS1115_REG_CONVERT, 0) != 0) {
        fprintf(stderr, "Failed to write conversion register address.\n");
        return -1;
    }
    if (read(fd, conversion_data, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data.\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t adc_value = (int16_t)((conversion_data[0] << 8) | conversion_data[1]);
    return adc_value;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        int16_t adc_value = ads1115_read_adc(i2c_fd);

        // Check for errors
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
        } else {
            // Print the ADC value
            printf("ADC Value: %d\n", adc_value);
        }

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // The program should never reach here due to the infinite loop
    close(i2c_fd);
    return 0;
}

