#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define MLX90614_TA 0x06
#define MLX90614_TO 0x07

int main() {
    int fd;
    uint16_t raw_temp, raw_ir;
    float temp_celsius, ir_temp;
    int retries = 3;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    while (1) {
        retries = 3;
        while (retries > 0) {
            if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
                perror("Failed to acquire bus access and/or talk to slave");
                retries--;
                usleep(100000); // Wait before retrying
                continue;
            }

            if (read(fd, &raw_temp, 2) != 2) {
                perror("Failed to read temperature data");
                retries--;
                usleep(100000); // Wait before retrying
                continue;
            }

            if (read(fd, &raw_ir, 2) != 2) {
                perror("Failed to read IR data");
                retries--;
                usleep(100000); // Wait before retrying
                continue;
            }

            temp_celsius = (float)raw_temp * 0.02 - 273.15;
            ir_temp = (float)raw_ir * 0.02 - 273.15;

            printf("Temperature: %.2f C, IR: %.2f C\n", temp_celsius, ir_temp);
            break; // Exit retry loop on success
        }

        if (retries == 0) {
            fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        }

        sleep(5);
    }

    close(fd);
    return 0;
}

