        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1)
    {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Transfer SPI data
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1)
    {
        syslog(LOG_ERR, "Failed to transfer SPI data: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Close SPI device
    close(fd);

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

