#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct gpiod_line_request_config config;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO
int init_gpio()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO value
int set_gpio_value(int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO initialized. Setting output to HIGH.\n");
    if (set_gpio_value(1) < 0) {
        fprintf(stderr, "Failed to set initial value. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO value");
            break; // Exit loop on error
        }

        // Validate reading
        if (value == 0 || value == 1) {
            // Print the state
            printf("GPIO %d: %d\n", GPIO_PIN, value);
        } else {
            fprintf(stderr, "Invalid GPIO reading: %d. Retrying...\n", value);
            // Retry after a short delay
            usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
            continue; // Skip the rest of the loop and retry
        }

        // Wait for a short interval
        usleep(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN 17
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Release GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO pin to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        // Print HIGH to standard output
        printf("HIGH\n");

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);

        // Set GPIO pin to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        // Print LOW to standard output
        printf("LOW\n");

        // Wait for 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Release GPIO line (should not reach here in normal execution due to the while(1) loop)
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LINE "line17"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Print GPIO value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return 0;
}

