#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define MEASURE_HUMID_CMD 0xE5

int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int read_si7021(int fd, uint8_t command) {
    uint8_t buf[2];
    int result;

    if (write(fd, &command, 1) != 1) {
        perror("Failed to write command to I2C device");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data from I2C device");
        return -1;
    }

    result = (buf[0] << 8) | buf[1];
    return result;
}

int validate_reading(int raw_value) {
    if (raw_value < 0 || raw_value > 65535) {
        return 0; // Invalid reading
    }
    return 1; // Valid reading
}

int main() {
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    int raw_temperature, raw_humidity;
    float temperature, humidity;
    int temp_reading, humid_reading;

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("Reading SI7021 sensor data... Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature
        temp_reading = read_si7021(i2c_fd, MEASURE_TEMP_CMD);
        if (temp_reading < 0) {
            fprintf(stderr, "Error reading temperature, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Read humidity
        humid_reading = read_si7021(i2c_fd, MEASURE_HUMID_CMD);
        if (humid_reading < 0) {
            fprintf(stderr, "Error reading humidity, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Validate readings
        if (validate_reading(temp_reading) && validate_reading(humid_reading)) {
            // Convert readings to Celsius and percentage humidity
            temperature = (175.72 * temp_reading) / 65536.0 - 46.85;
            humidity = (125.0 * humid_reading) / 65536.0 - 6.0;

            // Get current timestamp
            current_time = time(NULL);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print the data
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Invalid temperature or humidity reading, skipping.\n");
        }

        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000 // Disable comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0000 // Disable comparator
#define ADS1115_CONFIG_COMP_QUE_ENABLE 0x0001 // Enable comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an ADS1115 register
int write_ads1115_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an ADS1115 register
int read_ads1115_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115_value(int fd) {
    uint8_t buf[2];
    uint8_t reg = ADS1115_REG_CONVERT;

    // Write the conversion register address
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write conversion register address");
        return -1;
    }

    // Read the conversion value
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read conversion value");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t value = (buf[0] << 8) | buf[1];
    return value;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        int16_t value = read_ads1115_value(i2c_fd);
        if (value < 0) {
            fprintf(stderr, "Error reading ADC value. Exiting.\n");
            break;
        }

        // Print the value to standard output
        printf("ADC Value: %d\n", value);

        // Wait for 1 second
        sleep(1);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

