// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(chip, pin, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    if (gpiod_line_release(chip, pin) < 0) {
        fprintf(stderr, "Error releasing line %d\n", pin);
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO pin
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(chip, pin, &config, 0) < 0) {
        fprintf(stderr, "Error requesting line %d\n", pin);
        return -1;
    }

    if (strcmp(direction, "out") != 0 && strcmp(direction, "input") != 0) {
        fprintf(stderr, "Invalid direction: %s\n", direction);
        return -1;
    }

    if (strcmp(direction, "out") == 0) {
        if (gpiod_line_set_value(chip, pin, 0) < 0) {
            fprintf(stderr, "Error setting value for line %d\n", pin);
            return -1;
        }
    } else if (strcmp(direction, "input") == 0) {
        if (gpiod_line_get_value(chip, pin) < 0) {
            fprintf(stderr, "Error getting value for line %d\n", pin);
            return -1;
        }
    }

    return 0;
}

