    printf("GPIO 8: %d, GPIO 9: %d, GPIO 10: %d, GPIO 11: %d, GPIO 23: %d, GPIO 24: %d\n",
           gpio_get_value(chip, GPIO_8), gpio_get_value(chip, GPIO_9), gpio_get_value(chip, GPIO_10),
           gpio_get_value(chip, GPIO_11), gpio_get_value(chip, GPIO_23), gpio_get_value(chip, GPIO_24));
}

