    if (line8) gpiod_line_release(line8);
    if (line9) gpiod_line_release(line9);
    if (line10) gpiod_line_release(line10);
    if (line11) gpiod_line_release(line11);
    if (line23) gpiod_line_release(line23);
    if (line24) gpiod_line_release(line24);
    if (chip) gpiod_chip_close(chip);
}

