        fprintf(stderr, "Error opening chip %s\n", CHIP_NAME);
        return 1;
    }

    // Get line pointers for each GPIO pin
    line8 = gpiod_chip_get_line(chip, GPIO_8);
    line9 = gpiod_chip_get_line(chip, GPIO_9);
    line10 = gpiod_chip_get_line(chip, GPIO_10);
    line11 = gpiod_chip_get_line(chip, GPIO_11);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);

    if (!line8 || !line9 || !line10 || !line11 || !line23 || !line24) {
        fprintf(stderr, "Error getting line %d\n", GPIO_8);
        cleanup();
        return 1;
    }

    // Export and set direction for each GPIO pin
    if (gpio_export(GPIO_8) < 0 || gpio_set_direction(GPIO_8, "out") < 0) goto cleanup_exit;
    if (gpio_export(GPIO_9) < 0 || gpio_set_direction(GPIO_9, "out") < 0) goto cleanup_exit;
    if (gpio_export(GPIO_10) < 0 || gpio_set_direction(GPIO_10, "out") < 0) goto cleanup_exit;
    if (gpio_export(GPIO_11) < 0 || gpio_set_direction(GPIO_11, "out") < 0) goto cleanup_exit;
    if (gpio_export(GPIO_23) < 0 || gpio_set_direction(GPIO_23, "out") < 0) goto cleanup_exit;
    if (gpio_export(GPIO_24) < 0 || gpio_set_direction(GPIO_24, "out") < 0) goto cleanup_exit;

    // Main loop
    for (int i = 0; i < NUM_CYCLES; i++) {
        // Set GPIO pins to HIGH
        gpio_set_value(GPIO_8, 1);
        gpio_set_value(GPIO_9, 1);
        gpio_set_value(GPIO_10, 1);
        gpio_set_value(GPIO_11, 1);
        gpio_set_value(GPIO_23, 1);
        gpio_set_value(GPIO_24, 1);
        report_state();
        usleep(100000); // 100ms

        // Set GPIO pins to LOW
        gpio_set_value(GPIO_8, 0);
        gpio_set_value(GPIO_9, 0);
        gpio_set_value(GPIO_10, 0);
        gpio_set_value(GPIO_11, 0);
        gpio_set_value(GPIO_23, 0);
        gpio_set_value(GPIO_24, 0);
        report_state();
        usleep(100000); // 100ms
    }

cleanup_exit:
    cleanup();
    return 0;
}

