#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DHT11_TIMEOUT_US 100000 // 100ms

// Structure to hold DHT11 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT11Data;

// Global variables for GPIO line and chip
struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line) {
        gpiod_line_release(line);
    }
    exit(0);
}

// Function to initialize GPIO
int init_gpio() {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "dht11";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to read DHT11 data
DHT11Data read_dht11() {
    DHT11Data data = {0.0, 0.0, 0};
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    int i, j;

    // Set line to output
    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "dht11";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    output_config.value = 0; // Set to 0 to drive the line low

    if (gpiod_line_request(line, &output_config, 0) < 0) {
        perror("Error requesting GPIO line for output");
        data.valid = 0;
        return data;
    }

    // Send start signal
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Error setting GPIO line high");
        data.valid = 0;
        return data;
    }
    usleep(1000); // 1ms

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line low");
        data.valid = 0;
        return data;
    }
    usleep(1000); // 1ms

    // Wait for response
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > DHT11_TIMEOUT_US) {
            fprintf(stderr, "DHT11 timeout waiting for response\n");
            data.valid = 0;
            return data;
        }
        usleep(100); // Check every 100us
    }

    // Read data
    for (i = 0; i < 40; i++) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > DHT11_TIMEOUT_US) {
                fprintf(stderr, "DHT11 timeout waiting for data bit\n");
                data.valid = 0;
                return data;
            }
            usleep(100); // Check every 100us
        }

        struct timespec end_data;
        clock_gettime(CLOCK_MONOTONIC, &end_data);
        long time_taken = (end_data.tv_sec - start.tv_sec) * 1000000 + (end_data.tv_nsec - start.tv_nsec) / 1000;

        if (time_taken > 40) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Verify checksum
    if (raw_data[4] != ((raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF)) {
        fprintf(stderr, "DHT11 checksum error\n");
        data.valid = 0;
        return data;
    }

    // Convert data
    data.humidity = (float)((raw_data[0] << 8) + raw_data[1]) / 10.0;
    data.temperature = (float)(((raw_data[2] & 0x7F) << 8) + raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data.temperature *= -1.0;
    }

    return data;
}

// Function to print DHT11 data
void print_dht11_data(DHT11Data data) {
    if (data.valid) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", data.temperature, data.humidity);
    } else {
        fprintf(stderr, "Invalid DHT11 data\n");
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        DHT11Data data = read_dht11();
        print_dht11_data(data);
        sleep(5);
    }

    return 0;
}

