#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_PIN 2

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function prototypes
int init_gpio(void);
int set_gpio_value(int value);
int read_gpio_value(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Set GPIO value
int set_gpio_value(int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Read GPIO value
int read_gpio_value(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    printf("Cleaning up GPIO...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Error installing signal handler");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        printf("Cycle %d:\n", i + 1);
        for (int j = 0; j < 3; j++) {
            // Set GPIO value to HIGH
            if (set_gpio_value(1) < 0) {
                fprintf(stderr, "Failed to set GPIO value HIGH. Exiting.\n");
                cleanup_gpio();
                return 1;
            }
            printf("  HIGH\n");
            sleep(1);

            // Read GPIO value
            int value = read_gpio_value();
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO value. Exiting.\n");
                cleanup_gpio();
                return 1;
            }
            printf("  GPIO Value: %d\n", value);
            sleep(1);

            // Set GPIO value to LOW
            if (set_gpio_value(0) < 0) {
                fprintf(stderr, "Failed to set GPIO value LOW. Exiting.\n");
                cleanup_gpio();
                return 1;
            }
            printf("  LOW\n");
            sleep(1);
        }
        printf("\n");
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

