    // Release GPIO lines
    if (line_2) {
        gpiod_line_release(line_2);
    }
    if (line_3) {
        gpiod_line_release(line_3);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set GPIO pin state
int set_gpio_state(int gpio, int state)
{
    struct gpiod_line *line = NULL;
    int ret;

    if (gpio == GPIO_2) {
        line = line_2;
    } else if (gpio == GPIO_3) {
        line = line_3;
    } else if (gpio == GPIO_17) {
        line = line_17;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    if (state == 1) {
        ret = gpiod_line_set_value(line, 1);
    } else {
        ret = gpiod_line_set_value(line, 0);
    }

    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d: %d\n", gpio, state, ret);
        return -1;
    }

    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", chip);
        return 1;
    }

    // Get GPIO lines
    line_2 = gpiod_chip_get_line(chip, GPIO_2);
    line_3 = gpiod_chip_get_line(chip, GPIO_3);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_2 || !line_3 || !line_17) {
        fprintf(stderr, "Error getting GPIO line: %d, %d, %d\n", GPIO_2, GPIO_3, GPIO_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_2, "gpio2_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_2, gpiod_line_request_output(line_2, "gpio2_output", 0));
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_3, "gpio3_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_3, gpiod_line_request_output(line_3, "gpio3_output", 0));
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_17, "gpio17_output", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", GPIO_17, gpiod_line_request_output(line_17, "gpio17_output", 0));
        gpiod_line_release(line_2);
        gpiod_line_release(line_3);
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to HIGH
        if (set_gpio_state(GPIO_2, 1) < 0) {
            break; // Exit loop on error
        }
        printf("GPIO 2: HIGH\n");
        fflush(stdout);

        // Set GPIO 3 to LOW
        if (set_gpio_state(GPIO_3, 0) < 0) {
            break; // Exit loop on error
        }
        printf("GPIO 3: LOW\n");
        fflush(stdout);

        // Set GPIO 17 to HIGH
        if (set_gpio_state(GPIO_17, 1) < 0) {
            break; // Exit loop on error
        }
        printf("GPIO 17: HIGH\n");
        fflush(stdout);

        // Set GPIO 2 to LOW
        if (set_gpio_state(GPIO_2, 0) < 0) {
            break; // Exit loop on error
        }
        printf("GPIO 2: LOW\n");
        fflush(stdout);

        // Set GPIO 3 to HIGH
        if (set_gpio_state(GPIO_3, 1) < 0) {
            break; // Exit loop on error
        }
        printf("GPIO 3: HIGH\n");
        fflush(stdout);

        // Set GPIO 17 to LOW
        if (set_gpio_state(GPIO_17, 0) < 0) {
            break; // Exit loop on error
        }
        printf("GPIO 17: LOW\n");
        fflush(stdout);

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Release GPIO lines and close chip (should not reach here in normal execution due to the signal handler)
    gpiod_line_release(line_2);
    gpiod_line_release(line_3);
    gpiod_line_release(line_17);
    gpiod_chip_close(chip);

    return 0;
}

