}

// Initialize SPI
int spi_init(int channel, int speed)
{
    int fd;
    char spi_device[20];

    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", channel, channel);

    fd = open(spi_device, O_RDWR);
    if (fd < 0)
    {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1)
    {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1)
    {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Read from MCP3008 ADC
int spi_read(int channel, int channel_num)
{
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;                  // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 1)
    {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

