#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 2
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int i;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set PWM duty cycle to 0
    gpioPWM(PWM_GPIO, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Driving PWM on GPIO %d. Press Ctrl+C to exit.\n", PWM_GPIO);

    while (!terminate) {
        // Generate a sequence of PWM duty cycles
        for (duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle++) {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            fflush(stdout);
            gpioDelay(100000); // 0.1 seconds
        }

        for (duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle--) {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("Duty cycle: %d\n", duty_cycle);
            fflush(stdout);
            gpioDelay(100000); // 0.1 seconds
        }
    }

    // Clean up and exit
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

