#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// Define the I2C address of the OPT3001
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Function to write a byte to a specific register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }
    return 0;
}

// Function to read a byte from a specific register
int read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from register");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from a specific register
int read_16bit(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from register");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read the result from the OPT3001
int read_opt3001(int fd, uint16_t *result) {
    uint8_t config_value = 0xB0; // Continuous conversion mode, 100ms conversion time
    if (write_register(fd, CONFIG_REG, config_value) != 0) {
        return -1;
    }
    usleep(100000); // Wait for conversion to complete (100ms)
    uint16_t raw_result;
    if (read_16bit(fd, RESULT_REG, &raw_result) != 0) {
        return -1;
    }
    *result = raw_result;
    return 0;
}

int main() {
    int fd;
    uint16_t result;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Read the result from the OPT3001
    if (read_opt3001(fd, &result) != 0) {
        fprintf(stderr, "Failed to read OPT3001 result\n");
        close(fd);
        return 1;
    }

    // Print the result to standard output
    printf("Result: %u\n", result);

    // Close the I2C device
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 500

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Print GPIO value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return 0;
}

