// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int channel);
void set_gpio_output(int pin, int value);
