// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT)
    {
        syslog(LOG_INFO, "Received SIGINT, shutting down...");
        program_running = 0;
    }
}

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len)
{
    int fd;
    struct spi_ioc_transfer tr;

    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0)
    {
        syslog(LOG_ERR, "Failed to open SPI device: %s", strerror(errno));
        return -1;
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = len;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0)
    {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Read MCP3008 function
int read_mcp3008(int channel)
{
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(tx_buf, rx_buf, 3) != 0)
    {
        syslog(LOG_ERR, "Failed to read MCP3008 channel %d", channel);
        return -1;
    }

    // Extract ADC value
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Set GPIO output function
void set_gpio_output(int pin, int value)
{
    digitalWrite(pin, value);
}

int main(void)
{
    int adc_value;
    FILE *fp;
    char log_message[256];

    // Initialize syslog
    openlog("gpio4", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1)
    {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
    }

    // Initialize BCM2835 library
    if (!bcm2835_init())
    {
        syslog(LOG_ERR, "Failed to initialize BCM2835 library: %s", strerror(errno));
        return 1;
    }

    // Configure GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);

    syslog(LOG_INFO, "Program started");

    while (program_running)
    {
        // Read ADC value from MCP3008
        adc_value = read_mcp3008(MCP3008_CHANNEL);

        if (adc_value != -1)
        {
            // Set GPIO output based on ADC value
            if (adc_value > 500)
            {
                set_gpio_output(GPIO_PIN, HIGH);
            }
            else
            {
                set_gpio_output(GPIO_PIN, LOW);
            }

            // Log the state
            snprintf(log_message, sizeof(log_message), "ADC Value: %d, GPIO State: %s", adc_value, (digitalRead(GPIO_PIN) == HIGH) ? "HIGH" : "LOW");
            syslog(LOG_INFO, "%s", log_message);
        }
        else
        {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        // Delay for 100ms
        delay(100);
    }

    // Clean up and exit
    syslog(LOG_INFO, "Program exiting");
    set_gpio_output(GPIO_PIN, LOW); // Set GPIO to LOW before exiting
    bcm2835_close(); // Close BCM2835 library
    closelog();

    return 0;
}

