// Define GPIO pin for interrupt
#define INTERRUPT_PIN 4

// Define interrupt handler function
void interrupt_handler(int signum)
{
    printf("\nInterrupt signal received: %d\n", signum);
    digitalWrite(GPIO_PIN, LOW);
    digitalWrite(INTERRUPT_PIN, LOW);
    exit(signum);
}

// Define function to read data from SPI
int read_spi_data(int fd, unsigned char *data, int len)
{
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)0, // Dummy transmit buffer
        .rx_buf = (unsigned long)data, // Receive buffer
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    return 0;
}

// Define function to write data to GPIO
void write_gpio_data(int fd, unsigned char data)
{
    unsigned char buf[2];
    buf[0] = data;
    buf[1] = 0x00; // Dummy byte for reading

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)buf, // Transmit buffer
        .rx_buf = (unsigned long)buf, // Receive buffer
        .len = 2,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return;
    }
}

int main()
{
    int fd;
