        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);
    digitalWrite(GPIO_PIN, HIGH);

    // Set interrupt pin as input
    pinMode(INTERRUPT_PIN, INPUT);
    pullUpDnControl(INTERRUPT_PIN, PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler
    if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, &interrupt_handler) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Configure SPI mode
    unsigned char mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(fd);
        return 1;
    }

    // Configure bits per word
    unsigned char bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return 1;
    }

    // Configure max speed hz
    unsigned int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data from SPI
        ret = read_spi_data(fd, data, 2);
