#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

struct gpiod_chip *chip;
struct gpiod_line *line17, *line18;
volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error: Could not get GPIO %d\n", GPIO_17);
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error: Could not get GPIO %d\n", GPIO_18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output\n", GPIO_17);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line18, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d for output\n", GPIO_18);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 17 to HIGH
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to HIGH\n", GPIO_17);
            break;
        }

        // Set GPIO 18 to LOW
        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to LOW\n", GPIO_18);
            break;
        }

        // Print current state
        printf("GPIO 17: HIGH, GPIO 18: LOW\n");

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line18);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

