        log_data(gpio17_value, gpio18_value, gpio22_value, gpio27_value, adc_value);

        // Wait for 0.1 seconds
        delay(100);
    }

    return 0;
}

// Initialize GPIO pins
void gpio_init(void)
{
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1)
    {
        fprintf(stderr, "wiringPiSetupGpio failed\n");
        exit(1);
    }

    // Set GPIO pins as output
    pinMode(GPIO17, OUTPUT);
    pinMode(GPIO18, OUTPUT);
    pinMode(GPIO22, OUTPUT);
    pinMode(GPIO27, OUTPUT);

    // Set initial values
    gpio_set_output(GPIO17, 0);
    gpio_set_output(GPIO18, 0);
    gpio_set_output(GPIO22, 0);
    gpio_set_output(GPIO27, 0);
}

// Set GPIO pin as output
void gpio_set_output(int pin, int value)
{
    digitalWrite(pin, value);
}

// Set GPIO pin as input
void gpio_set_input(int pin)
{
    pinMode(pin, INPUT);
}

// Initialize SPI
int spi_init(void)
{
    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0)
    {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0)
    {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0)
    {
        fprintf(stderr, "Failed to set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0)
    {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ADC value from MCP3008
int spi_read(int channel)
{
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = MCP3008_COMMAND | MCP3008_READ_COMMAND_DATA_SIZE;
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4;
    tx_buf[2] = 0x00;

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0)
    {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Cleanup GPIO and SPI resources
void cleanup(void)
{
    gpio_set_output(GPIO17, 0);
    gpio_set_output(GPIO18, 0);
    gpio_set_output(GPIO22, 0);
    gpio_set_output(GPIO27, 0);
    close(spi_fd);
}

// Log data to standard output
void log_data(int gpio17_value, int gpio18_value, int gpio22_value, int gpio27_value, int adc_value)
{
    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s.%06ld, GPIO17: %d, GPIO18: %d, GPIO22: %d, GPIO27: %d, ADC: %d\n",
           timestamp, tv.tv_usec, gpio17_value, gpio18_value, gpio22_value, gpio27_value, adc_value);
}

