// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s\n", CHIP_NAME);
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line %d\n", pin);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "gpio_export", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d as output\n", pin);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

