// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s\n", CHIP_NAME);
