// Function to set GPIO pin state
int set_gpio_state(int gpio, int state)
{
    struct gpiod_line *line = NULL;

    if (gpio == GPIO_17) {
        line = line_17;
    } else if (gpio == GPIO_22) {
        line = line_22;
    } else if (gpio == GPIO_27) {
        line = line_27;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO %d to state %d\n", gpio, state);
        return -1;
    }

    return 0;
}

