            if (read_temperature(device_id, &temperature) == 0) {
                printf("Sensor: %s, Temperature: %.2f °C\n", device_id, temperature);
                read_success = 1;
            } else {
                free(device_id);
                device_id = NULL; // Reset device_id if read fails
            }
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read temperature from all sensors.\n");
        }

        if (device_id != NULL) {
            free(device_id);
        }

        if (time(NULL) - start_time > 5) {
