    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_htu21d(int fd, uint8_t command, uint16_t *reading) {
    uint8_t buf[3];
    buf[0] = command;
    buf[1] = 0x00; // Dummy byte
    buf[2] = 0x00; // Dummy byte

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }

    usleep(100000); // Wait for measurement (at least 50ms)

    if (read(fd, buf, 3) != 3) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *reading = (buf[0] << 8) | buf[1];
    return 0;
}

int validate_reading(uint16_t raw_reading) {
    // Check for valid temperature range
    if (raw_reading < 0x0800 || raw_reading > 0xFFFC) {
        fprintf(stderr, "Invalid temperature reading: 0x%04X\n", raw_reading);
        return -1;
    }

    // Check for valid humidity range
    if (raw_reading < 0x0000 || raw_reading > 0x7FFF) {
        fprintf(stderr, "Invalid humidity reading: 0x%04X\n", raw_reading);
        return -1;
    }

    return 0;
}

int main() {
    int fd;
    uint16_t raw_temperature, raw_humidity;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    printf("HTU21D sensor reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read temperature
        if (read_htu21d(fd, MEASURE_TEMP_CMD, &raw_temperature) == 0) {
            if (validate_reading(raw_temperature) == 0) {
                current_time = time(NULL);
                time_info = localtime(&current_time);
                strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s - Temperature: %d * 0.01 degC\n", time_string, raw_temperature);
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        // Read humidity
        if (read_htu21d(fd, MEASURE_HUMID_CMD, &raw_humidity) == 0) {
            if (validate_reading(raw_humidity) == 0) {
                current_time = time(NULL);
                time_info = localtime(&current_time);
                strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s - Humidity: %d %%RH\n", time_string, raw_humidity);
            }
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        sleep(60);
    }

    // Close I2C device
    close(fd);

    printf("HTU21D sensor reader stopped.\n");

    return 0;
}

