// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an ADXL345 register
int read_register(int fd, uint8_t reg) {
    int value = i2c_smbus_read_byte_data(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single byte to an ADXL345 register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from ADXL345 registers
int16_t read_16bit(int fd, uint8_t low_reg, uint8_t high_reg) {
    int low = read_register(fd, low_reg);
    if (low < 0) return 0; // Return 0 on error

    int high = read_register(fd, high_reg);
    if (high < 0) return 0; // Return 0 on error

    return (int16_t)((high << 8) | low);
}

// Function to read the X, Y, and Z axis values from the ADXL345
void read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    *x = read_16bit(fd, ADXL345_DATAX0, ADXL345_DATAX1);
    *y = read_16bit(fd, ADXL345_DATAY0, ADXL345_DATAY1);
    *z = read_16bit(fd, ADXL345_DATAZ0, ADXL345_DATAZ1);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set ADXL345 to measurement mode
    if (write_register(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;
        read_acceleration(i2c_fd, &x, &y, &z);

        // Print the acceleration values
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // The program should never reach here due to the infinite loop.
    // However, it's good practice to include a close(i2c_fd) statement.
    close(i2c_fd);
    return 0;
}

