#define PWM_GPIO 17
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int duty_cycle;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set PWM duty cycle to 0
    gpioPWM(PWM_GPIO, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("PWM output on GPIO %d, frequency %d Hz, range %d\n", PWM_GPIO, PWM_FREQUENCY, PWM_RANGE);

    while (!terminate) {
        // Generate random duty cycle between 0 and 1000
        duty_cycle = rand() % PWM_RANGE;

        // Set PWM duty cycle
        gpioPWM(PWM_GPIO, duty_cycle);

        // Print the current duty cycle
        printf("Duty cycle: %d\n", duty_cycle);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

