// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_WTIME           (0x03)
#define TCS34725_AILTL           (0x04)
#define TCS34725_AILTH           (0x05)
#define TCS34725_AIHTL           (0x06)
#define TCS34725_AIHTH           (0x07)
#define TCS34725_ID              (0x12)
#define TCS34725_STATUS          (0x13)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_ENABLE_PON      (0x01)
#define TCS34725_ENABLE_AEN      (0x02)
#define TCS34725_ENABLE_AIEN     (0x10)

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS  (0x00)
#define TCS34725_INTEGRATIONTIME_24MS   (0x01)
#define TCS34725_INTEGRATIONTIME_44MS   (0x02)
#define TCS34725_INTEGRATIONTIME_101MS  (0x03)
#define TCS34725_INTEGRATIONTIME_154MS  (0x04)
#define TCS34725_INTEGRATIONTIME_242MS  (0x05)
#define TCS34725_INTEGRATIONTIME_424MS  (0x06)
#define TCS34725_INTEGRATIONTIME_1016MS (0x07)

// Gain
#define TCS34725_GAIN_1X          (0x00)
#define TCS34725_GAIN_4X          (0x01)
#define TCS34725_GAIN_16X         (0x02)
#define TCS34725_GAIN_60X         (0x03)

int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to write a byte to a TCS34725 register
int tcs34725_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from a TCS34725 register
int tcs34725_read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Check device ID
    uint8_t id;
    if (tcs34725_read_register(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and ALS
    if (tcs34725_write_register(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) {
        fprintf(stderr, "Error enabling sensor\n");
        return -1;
    }

    // Set integration time (2.4ms)
    if (tcs34725_write_register(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS) != 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain (1x)
    if (tcs34725_write_register(fd, TCS34725_GAIN, TCS34725_GAIN_1X) != 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

// Function to read a 16-bit value from the TCS34725 sensor
int tcs34725_read_16bit(int fd, uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    if (tcs34725_write_register(fd, TCS34725_COMMAND_BIT | reg, 0) != 0) {
        fprintf(stderr, "Error writing register address for read\n");
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value\n");
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize TCS34725 sensor\n");
        close(i2c_fd);
        return 1;
    }

    printf("TCS34725 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        uint16_t clear, red, green, blue;

        // Read sensor data
        if (tcs34725_read_16bit(i2c_fd, TCS34725_CDATA, &clear) != 0) {
            fprintf(stderr, "Error reading clear data\n");
            continue; // Continue to the next iteration
        }
        if (tcs34725_read_16bit(i2c_fd, TCS34725_RDATA, &red) != 0) {
            fprintf(stderr, "Error reading red data\n");
            continue; // Continue to the next iteration
        }
        if (tcs34725_read_16bit(i2c_fd, TCS34725_GDATA, &green) != 0) {
            fprintf(stderr, "Error reading green data\n");
            continue; // Continue to the next iteration
        }
        if (tcs34725_read_16bit(i2c_fd, TCS34725_BDATA, &blue) != 0) {
            fprintf(stderr, "Error reading blue data\n");
            continue; // Continue to the next iteration
        }

        // Print the data
        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);

        // Wait for 0.2 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

