  struct v4l2_format fmt ;
  struct v4l2_requestbuffers req ;
  struct v4l2_buffer buf ;
  unsigned char *buffer ;
  int i, r ;
  char filename [256] ;

  printf ("Testing camera module...\n") ;

  fd = open ("/dev/video0", O_RDWR) ;
  if (fd < 0)
  {
    printf ("Error opening /dev/video0: %s\n", strerror (errno)) ;
    return 1 ;
  }

  if (ioctl (fd, VIDIOC_QUERYCAP, &cap) < 0)
  {
    printf ("Error querying capabilities: %s\n", strerror (errno)) ;
    close (fd) ;
    return 1 ;
  }

  if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE))
  {
    printf ("Error: /dev/video0 is not a video capture device\n") ;
    close (fd) ;
    return 1 ;
  }

  if (!(cap.capabilities & V4L2_CAP_STREAMING))
  {
    printf ("Error: /dev/video0 does not support streaming I/O\n") ;
    close (fd) ;
    return 1 ;
  }

  if (strcmp (cap.card, "Broadcom") != 0 && strcmp (cap.card, "Raspberry Pi Camera") != 0)
  {
    printf ("Error: /dev/video0 is not a Raspberry Pi camera module\n") ;
    close (fd) ;
    return 1 ;
  }

  if (strcmp (cap.driver, DEVID) != 0)
  {
    printf ("Error: /dev/video0 is not a Raspberry Pi camera module\n") ;
    close (fd) ;
    return 1 ;
  }

  memset (&fmt, 0, sizeof (fmt)) ;
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE ;
  fmt.fmt.pix.width = 640 ;
  fmt.fmt.pix.height = 480 ;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV ;
  fmt.fmt.pix.field = V4L2_FIELD_INTERLACED ;

  if (ioctl (fd, VIDIOC_S_FMT, &fmt) < 0)
  {
    printf ("Error setting format: %s\n", strerror (errno)) ;
    close (fd) ;
    return 1 ;
  }

  memset (&req, 0, sizeof (req)) ;
  req.count = 1 ;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE ;
  req.memory = V4L2_MEMORY_MMAP ;

  if (ioctl (fd, VIDIOC_REQBUFS, &req) < 0)
  {
    printf ("Error requesting buffers: %s\n", strerror (errno)) ;
    close (fd) ;
    return 1 ;
  }

  memset (&buf, 0, sizeof (buf)) ;
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE ;
  buf.memory = V4L2_MEMORY_MMAP ;
  buf.index = 0 ;

  if (ioctl (fd, VIDIOC_QUERYBUF, &buf) < 0)
  {
    printf ("Error querying buffer: %s\n", strerror (errno)) ;
    close (fd) ;
    return 1 ;
  }

  buffer = mmap (NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset) ;
  if (buffer == MAP_FAILED)
  {
    printf ("Error mapping buffer: %s\n", strerror (errno)) ;
    close (fd) ;
    return 1 ;
  }

  memset (&buf, 0, sizeof (buf)) ;
  buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE ;
  buf.memory = V4L2_MEMORY_MMAP ;
  buf.index = 0 ;

  if (ioctl (fd, VIDIOC_QBUF, &buf) < 0)
  {
    printf ("Error queuing buffer: %s\n", strerror (errno)) ;
    munmap (buffer, buf.length) ;
    close (fd) ;
    return 1 ;
  }

  enum {
    CAPTURE
  } q = CAPTURE ;

  if (ioctl (fd, VIDIOC_STREAMON, &q) < 0)
  {
    printf ("Error starting stream: %s\n", strerror (errno)) ;
    munmap (buffer, buf.length) ;
    close (fd) ;
    return 1 ;
  }

  snprintf (filename, sizeof (filename), "/tmp/camera%d.jpg", fd) ;
  printf ("Saving image to %s\n", filename) ;

  r = read (fd, buffer, buf.length) ;
  if (r < 0)
  {
    printf ("Error reading image: %s\n", strerror (errno)) ;
    munmap (buffer, buf.length) ;
    close (fd) ;
    return 1 ;
  }

  if (r != buf.length)
  {
    printf ("Warning: read %d bytes, expected %d\n", r, buf.length) ;
  }

  if (ioctl (fd, VIDIOC_DQBUF, &buf) < 0)
  {
    printf ("Error dequeuing buffer: %s\n", strerror (errno)) ;
    munmap (buffer, buf.length) ;
    close (fd) ;
    return 1 ;
  }

  if (ioctl (fd, VIDIOC_STREAMOFF, &q) < 0)
  {
    printf ("Error stopping stream: %s\n", strerror (errno)) ;
    munmap (buffer, buf.length) ;
    close (fd) ;
    return 1 ;
  }

  munmap (buffer, buf.length) ;
  close (fd) ;

  printf ("Done.\n") ;
  return 0 ;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_22 22
#define GPIO_27 27

struct gpiod_chip *chip;
struct gpiod_line *line22, *line27;
volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 0.01 seconds

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get line handles for GPIO 22 and GPIO 27
    line22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line22) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", GPIO_22);
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", GPIO_27);
        gpiod_line_release(line22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line22, "digital_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %d\n", GPIO_22, ret);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line27, "digital_output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %d\n", GPIO_27, ret);
        gpiod_line_release(line22);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 22 to HIGH
        ret = gpiod_line_set_value(line22, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to HIGH: %d\n", GPIO_22, ret);
            break;
        }

        // Set GPIO 27 to LOW
        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to LOW: %d\n", GPIO_27, ret);
            break;
        }

        // Print current state
        printf("GPIO 22: HIGH, GPIO 27: LOW\n");

        // Sleep for 0.01 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line22);
    gpiod_line_release(line27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define SSD1306 I2C address and screen dimensions
#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

// I2C file descriptor
int i2c_fd;

// Function prototypes
int ssd1306_init(int fd);
int ssd1306_clear(int fd);
int ssd1306_set_cursor(int fd, int x, int y);
int ssd1306_write_string(int fd, const char *str);
int ssd1306_write_int(int fd, int num);
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize the SSD1306 display
int ssd1306_init(int fd) {
    // Initialization sequence (refer to SSD1306 datasheet)
    unsigned char init_sequence[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio/oscillator frequency
        0xA8, 0x3F, // Multiplex ratio
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode
        0xA1,       // Segment remap
        0xC8,       // COM output scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        unsigned char command = init_sequence[i];
        if (write(fd, &command, 1) != 1) {
            perror("Failed to write to I2C device");
            return -1;
        }
        usleep(1000); // Wait for command to complete
    }
    return 0;
}

// Function to clear the display
int ssd1306_clear(int fd) {
    unsigned char clear_command[] = {0x40, 0x00};
    if (write(fd, clear_command, sizeof(clear_command)) != sizeof(clear_command)) {
        perror("Failed to clear display");
        return -1;
    }
    usleep(2000); // Wait for clear command to complete
    return 0;
}

// Function to set the cursor position
int ssd1306_set_cursor(int fd, int x, int y) {
    unsigned char command[] = {0x21, 0x00, x, y};
    if (write(fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to set cursor position");
        return -1;
    }
    return 0;
}

// Function to write a string to the display
int ssd1306_write_string(int fd, const char *str) {
    int i;
    for (i = 0; str[i] != '\0'; i++) {
        if (ssd1306_set_cursor(fd, i, 0) != 0) return -1;
        if (ssd1306_write_int(fd, str[i]) != 0) return -1;
    }
    return 0;
}

// Function to write an integer to the display
int ssd1306_write_int(int fd, int num) {
    char buffer[16];
    snprintf(buffer, sizeof(buffer), "%d", num);
    return ssd1306_write_string(fd, buffer);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize SSD1306 display
    if (ssd1306_init(i2c_fd) != 0) {
        fprintf(stderr, "SSD1306 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format time string
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Clear display
        if (ssd1306_clear(i2c_fd) != 0) {
            fprintf(stderr, "Failed to clear display.\n");
        }

        // Write time to display
        if (ssd1306_write_string(i2c_fd, time_str) != 0) {
            fprintf(stderr, "Failed to write time to display.\n");
        }

        // Write sensor readings to display
        if (ssd1306_write_int(i2c_fd, 1234) != 0) {
            fprintf(stderr, "Failed to write sensor reading to display.\n");
        }
        if (ssd1306_write_int(i2c_fd, 5678) != 0) {
            fprintf(stderr, "Failed to write sensor reading to display.\n");
        }

        // Update display
        if (ssd1306_clear(i2c_fd) != 0) {
            fprintf(stderr, "Failed to clear display before update.\n");
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clear display before exiting
    if (ssd1306_clear(i2c_fd) != 0) {
        fprintf(stderr, "Failed to clear display before exiting.\n");
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

