#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM1_PIN 8
#define PWM2_PIN 9
#define PWM3_PIN 11
#define PWM4_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM frequency and range
void set_pwm_frequency(int pin, int frequency, int range)
{
    gpioSetPWMfrequency(pin, frequency);
    gpioSetPWMrange(pin, range);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int pin, int duty_cycle)
{
    gpioPWM(pin, duty_cycle);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set PWM frequency and range for all four pins
    set_pwm_frequency(PWM1_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM2_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM3_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM4_PIN, PWM_FREQUENCY, PWM_RANGE);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle for each pin
        set_pwm_duty_cycle(PWM1_PIN, 128); // 50% duty cycle
        set_pwm_duty_cycle(PWM2_PIN, 128); // 50% duty cycle
        set_pwm_duty_cycle(PWM3_PIN, 128); // 50% duty cycle
        set_pwm_duty_cycle(PWM4_PIN, 128); // 50% duty cycle

        // Print the state to standard output
        printf("PWM1: %d, PWM2: %d, PWM3: %d, PWM4: %d\n", gpioGetPWMdutycycle(PWM1_PIN), gpioGetPWMdutycycle(PWM2_PIN), gpioGetPWMdutycycle(PWM3_PIN), gpioGetPWMdutycycle(PWM4_PIN));

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM output
    set_pwm_duty_cycle(PWM1_PIN, 0);
    set_pwm_duty_cycle(PWM2_PIN, 0);
    set_pwm_duty_cycle(PWM3_PIN, 0);
    set_pwm_duty_cycle(PWM4_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for HC-SR04
#define TRIGGER_PIN 17
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measure_pulse() {
    long start_time = 0, end_time = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_time = gpioTick();

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_duration = measure_pulse();

        if (pulse_duration > 0) {
            float distance = calculate_distance(pulse_duration);
            if (distance >= 0) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Error: Timeout waiting for echo\n");
        }

        gpioDelay(200); // Delay for 200ms
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 18
#define NUM_PIXELS 10

// Function to set the color of a pixel
void set_pixel_color(int gpio, int pixel_index, int red, int green, int blue) {
    if (pixel_index < 0 || pixel_index >= NUM_PIXELS) {
        fprintf(stderr, "Error: Invalid pixel index: %d\n", pixel_index);
        return;
    }

    gpioPWM(gpio, 255); // Set PWM duty cycle to 255 (full brightness)
    gpioSetMode(gpio, PI_OUTPUT); // Ensure GPIO is in output mode

    // Calculate the GPIO pin number for the current pixel
    int pin = gpio + (pixel_index * 10); // Assuming 10 GPIO pins per pixel

    // Set the GPIO pin to the desired color (example: red, green, blue)
    gpioWrite(pin, red);
    gpioWrite(pin + 1, green);
    gpioWrite(pin + 2, blue);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            set_pixel_color(GPIO_PIN, i, 255, 0, 0); // Red
            gpioDelay(10000); // 10ms delay
