// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers = NULL;
int n_buffers = 0;
int fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (buffers) {
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i].start) {
                munmap((void *)buffers[i].start, buffers[i].length);
