    dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    dig_H1 = buffer[25];

    uint8_t buffer_h[7];
    if (read(fd, buffer_h, 7) != 7) {
        perror("Failed to read humidity calibration data");
        return -1;
    }

    dig_H2 = (int16_t)buffer_h[0] | ((int16_t)buffer_h[1] << 8);
    dig_H3 = buffer_h[2];
    dig_H4 = (int16_t)(buffer_h[3] << 4) | (buffer_h[4] & 0x0F);
    dig_H5 = (int16_t)(buffer_h[5] << 4) | (buffer_h[4] >> 4);
    dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

// BME280 read data function
int bme280_read_data(int fd, float *temperature, float *pressure, float *humidity) {
    uint8_t buffer[8];
    if (read(fd, buffer, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    int32_t raw_pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    int32_t raw_temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);
    int32_t raw_humidity = ((int32_t)buffer[6] << 8) | (int32_t)buffer[7];

    // Temperature compensation
    double var1 = (raw_temperature / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    double var2 = ((raw_temperature / 131072.0 - dig_T1 / 8192.0) * (raw_temperature / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Pressure compensation
    double var3 = t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * dig_P6 / 32768.0;
    double var5 = var4 + var3 * dig_P5 * 2.0;
    double var6 = var5 / 4.0 + dig_P4 * 65536.0;
    double var7 = dig_P3 * var3 * var3 / 524288.0;
    double var8 = dig_P2 * var3 / 524288.0;
    double var9 = dig_P1 + var7 + var8;
    double p = 1048576.0 - raw_pressure;
    p = (p - var6 / 4096.0) * 6250.0 / var9;
    var3 = dig_P9 * p * p / 2147483648.0;
    var4 = p * dig_P8 / 32768.0;
    *pressure = (p + (var3 + var4 + dig_P7) / 16.0) / 100.0; // in hPa

    // Humidity compensation
    double var_H = t_fine - 76800.0;
    var_H = (raw_humidity - (dig_H4 * 64.0 + dig_H5 / 16384.0 * var_H)) * (dig_H2 / 65536.0 * (1.0 + dig_H6 / 67108864.0 * var_H * (1.0 + dig_H3 / 67108864.0 * var_H)));
    *humidity = var_H * (1.0 - dig_H1 * var_H / 524288.0);

    // Clamp humidity to 0-100%
    if (*humidity > 100.0) *humidity = 100.0;
    if (*humidity < 0.0) *humidity = 0.0;

    return 0;
}

// BME280 close function
void bme280_close(int fd) {
    close(fd);
}

// BME280 error exit function
void bme280_error_exit(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

int main(int argc, char *argv[]) {
    int i2c_address = BME280_ADDR;

    if (argc > 1) {
        bme280_address = strtol(argv[1], NULL, 0);
        printf("Using I2C address: 0x%x\n", bme280_address);
    }

    i2c_fd = i2c_setup(i2c_address);
    if (i2c_fd < 0) {
        bme280_error_exit("Failed to initialize I2C");
    }

    if (bme280_read_calibration_data(i2c_fd) < 0) {
        bme280_close(i2c_fd);
        bme280_error_exit("Failed to read calibration data");
    }

    // Set oversampling and power mode
    uint8_t ctrl_meas = (OVERSAMPLING_TEMP << 5) | (OVERSAMPLING_PRESS << 2) | 0x03; // Normal mode
    uint8_t ctrl_hum = OVERSAMPLING_HUM;
    uint8_t config = 0x00; // t_sb = 0.5ms, filter = off

    if (write(i2c_fd, &ctrl_hum, 1) != 1) {
        perror("Failed to write to CTRL_HUM_REG");
        bme280_close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write to CONFIG_REG");
        bme280_close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, &ctrl_meas, 1) != 1) {
        perror("Failed to write to CTRL_MEAS_REG");
        bme280_close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    float temperature, pressure, humidity;
    while (1) {
        if (bme280_read_data(i2c_fd, &temperature, &pressure, &humidity) == 0) {
            printf("Temperature: %.2f \u00b0C, Pressure: %.2f hPa, Humidity: %.2f %%\n", temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(5);
    }

    bme280_close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define LINE "line4"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 60;
    sleep_time.tv_nsec = 0;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", GPIO_PIN);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read GPIO line %d\n", GPIO_PIN);
            break;
        }

        // Print the value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep for 60 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1 0x6B

// Function to write a byte to an I2C device
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C device
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from an I2C device
int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the MPU6050
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (set power management register to 0)
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }
    return 0;
}

// Function to read the accelerometer data
int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    // Read the accelerometer data registers (0x3B to 0x3E)
    if (write(fd, (uint8_t[]){MPU6050_ACCEL_XOUT_H}, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    // Combine the high and low bytes to form 16-bit values
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

int main() {
    int fd;
    int16_t x, y, z;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Initialize the MPU6050
    if (init_mpu6050(fd) != 0) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the accelerometer data
        if (read_accelerometer(fd, &x, &y, &z) == 0) {
            // Print the accelerometer data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Wait for 0.01 seconds
        usleep(10000); // 10000 microseconds = 0.01 seconds
    }

    // Close the I2C device (this will never be reached in the current loop)
    close(fd);

    return 0;
}

