#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x27 // Replace with your HD44780 address

// Define HD44780 commands
#define HD44780_FUNCTION_SET 0x80
#define HD44780_DISPLAY_ON 0x04
#define HD44780_DISPLAY_OFF 0x04
#define HD44780_CURSOR_OFF 0x04
#define HD44780_CURSOR_ON 0x06
#define HD44780_BLINK_OFF 0x00
#define HD44780_BLINK_ON 0x08
#define HD44780_ENTRY_MODE_SET 0x06
#define HD44780_DISPLAY_SHIFT_LEFT 0x00
#define HD44780_DISPLAY_SHIFT_RIGHT 0x00
#define HD44780_DISPLAY_SHIFT_POSITION 0x00
#define HD44780_DISPLAY_SET_CURSOR_POSITION 0x01
#define HD44780_CLEAR_DISPLAY 0x01

// Function to write a command to the HD44780
int hd44780_write_command(int fd, unsigned char command) {
    unsigned char buf[2];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write command");
        return -1;
    }
    return 0;
}

// Function to write data to the HD44780
int hd44780_write_data(int fd, unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x40; // Data command
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Function to initialize the HD44780
int hd44780_init(int fd) {
    // Initialize the HD44780
    if (hd44780_write_command(fd, HD44780_FUNCTION_SET) != 0) {
        fprintf(stderr, "Failed to set function mode.\n");
        return -1;
    }
    if (hd44780_write_command(fd, HD44780_DISPLAY_ON) != 0) {
        fprintf(stderr, "Failed to turn display on.\n");
        return -1;
    }
    if (hd44780_write_command(fd, HD44780_ENTRY_MODE_SET) != 0) {
        fprintf(stderr, "Failed to set entry mode.\n");
        return -1;
    }
    if (hd44780_write_command(fd, HD44780_DISPLAY_SHIFT_LEFT) != 0) {
        fprintf(stderr, "Failed to set display shift.\n");
        return -1;
    }
    return 0;
}

// Function to clear the display
int hd44780_clear_display(int fd) {
    if (hd44780_write_command(fd, HD44780_CLEAR_DISPLAY) != 0) {
        fprintf(stderr, "Failed to clear display.\n");
        return -1;
    }
    return 0;
}

// Function to display a string on the HD44780
int hd44780_display_string(int fd, const char *str) {
    int i;
    for (i = 0; str[i] != '\0'; i++) {
        if (hd44780_write_data(fd, str[i]) != 0) {
            fprintf(stderr, "Failed to write character to display.\n");
            return -1;
        }
    }
    return 0;
}

int main() {
    int fd;
    char time_str[20];
    struct timespec ts;
    int i2c_msb, i2c_lsb;

    // Open the I2C device
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Initialize the HD44780
    if (hd44780_init(fd) != 0) {
        fprintf(stderr, "HD44780 initialization failed.\n");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        long milliseconds = ts.tv_nsec / 1000000;

        // Format the time string
        snprintf(time_str, sizeof(time_str), "%ld", milliseconds);

        // Clear the display
        if (hd44780_clear_display(fd) != 0) {
            fprintf(stderr, "Failed to clear display.\n");
            break;
        }

        // Display the time string
        if (hd44780_display_string(fd, time_str) != 0) {
            fprintf(stderr, "Failed to display time string.\n");
            break;
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Close the I2C device
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1 0x6B

// Function to write a byte to an I2C device
int i2c_write_byte(int file_descriptor, uint8_t device_address, uint8_t register_address, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = register_address;
    buffer[1] = value;
    if (write(file_descriptor, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from an I2C device
int i2c_read_word(int file_descriptor, uint8_t device_address, uint8_t register_address, uint16_t *value) {
    uint8_t buffer[2];
    if (write(file_descriptor, &register_address, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(file_descriptor, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (buffer[0] << 8) | buffer[1];
    return 0;
}

int main() {
    int file_descriptor;
    int i2c_address = MPU6050_ADDR;
    int i2c_bus = 1; // I2C bus number (usually 1 on Raspberry Pi)
    int retries = 3; // Number of retries for I2C operations
    int delay_ms = 100; // Delay between readings in milliseconds
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    uint8_t power_mode = 0; // Wake up the MPU6050

    // Open I2C device
    file_descriptor = open("/dev/i2c-1", O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(file_descriptor, I2C_SLAVE, i2c_address) < 0) {
        perror("Failed to set I2C slave address");
        close(file_descriptor);
        return 1;
    }

    // Wake up the MPU6050
    if (i2c_write_byte(file_descriptor, i2c_address, MPU6050_PWR_MGMT_1, power_mode) < 0) {
        close(file_descriptor);
        return 1;
    }

    // Read and print accelerometer data
    for (int i = 0; i < 100; i++) {
        if (i2c_read_word(file_descriptor, i2c_address, MPU6050_ACCEL_XOUT_H, &accel_x) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            i2c_write_byte(file_descriptor, i2c_address, MPU6050_PWR_MGMT_1, power_mode);
            usleep(10000); // Wait 10ms before retrying
            continue;
        }
        if (i2c_read_word(file_descriptor, i2c_address, MPU6050_ACCEL_XOUT_H + 2, &accel_y) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            i2c_write_byte(file_descriptor, i2c_address, MPU6050_PWR_MGMT_1, power_mode);
            usleep(10000); // Wait 10ms before retrying
            continue;
        }
        if (i2c_read_word(file_descriptor, i2c_address, MPU6050_ACCEL_XOUT_H + 4, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            i2c_write_byte(file_descriptor, i2c_address, MPU6050_PWR_MGMT_1, power_mode);
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        // Scale accelerometer data (assuming +/- 2g sensitivity)
        float accel_x_g = (float)accel_x / 16384.0f; // 16384 LSB/g
        float accel_y_g = (float)accel_y / 16384.0f;
        float accel_z_g = (float)accel_z / 16384.0f;

        printf("Accel X: %.2f g, Accel Y: %.2f g, Accel Z: %.2f g\n", accel_x_g, accel_y_g, accel_z_g);

        usleep(delay_ms * 1000); // Delay for 100ms
    }

    // Close I2C device
    close(file_descriptor);

    return 0;
}

