#define MQTT_TOPIC "sensor_data"
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define SENSOR3_GPIO 27
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_KEEPALIVE 60

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor(int gpio);
int publish_mqtt(const char *topic, const char *payload);
void signal_handler(int signum);
void cleanup();

// Function to read sensor value from GPIO pin
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to publish MQTT message
int publish_mqtt(const char *topic, const char *payload) {
    int ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing to topic %s: %s\n", topic, mosquitto_strerror(ret));
        return -1; // Indicate error
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Signal received, exiting...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        cleanup();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_loop_callback_set(mosq, NULL);

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Validate sensor readings
        if (sensor1_value >= 0 && sensor1_value <= 1) {
            char payload1[50];
            snprintf(payload1, sizeof(payload1), "Sensor1: %d", sensor1_value);
            if (publish_mqtt(MQTT_TOPIC, payload1) != 0) {
                fprintf(stderr, "Failed to publish Sensor1 data\n");
            }
        } else {
            fprintf(stderr, "Invalid reading from Sensor1\n");
        }

        if (sensor2_value >= 0 && sensor2_value <= 1) {
            char payload2[50];
            snprintf(payload2, sizeof(payload2), "Sensor2: %d", sensor2_value);
            if (publish_mqtt(MQTT_TOPIC, payload2) != 0) {
                fprintf(stderr, "Failed to publish Sensor2 data\n");
            }
        } else {
            fprintf(stderr, "Invalid reading from Sensor2\n");
        }

        if (sensor3_value >= 0 && sensor3_value <= 1) {
            char payload3[50];
            snprintf(payload3, sizeof(payload3), "Sensor3: %d", sensor3_value);
            if (publish_mqtt(MQTT_TOPIC, payload3) != 0) {
                fprintf(stderr, "Failed to publish Sensor3 data\n");
            }
        } else {
            fprintf(stderr, "Invalid reading from Sensor3\n");
        }

        gpioDelay(10000); // 0.01 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

