#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm
#define TIMEOUT_US 50000        // Timeout for echo pulse in microseconds

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int trigger_sensor();
long pulse_in(int pin, int level, uint32_t timeout_us);
float calculate_distance(long pulse_duration);
void log_data(float distance);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the HC-SR04 sensor
int trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Function to measure the pulse duration on the ECHO_PIN
long pulse_in(int pin, int level, uint32_t timeout_us) {
    long start_time = 0, end_time = 0;
    long pulse_duration = 0;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (start_time == 0) start_time = gpioTick();
        if (start_time == 0 && gpioTick() - start_time > timeout_us) return -1; // Timeout
    }

    // Measure the pulse duration
    while (gpioRead(pin) == level) {
        if (end_time == 0) end_time = gpioTick();
        if (end_time == 0 && gpioTick() - end_time > timeout_us) return -1; // Timeout
    }

    pulse_duration = end_time - start_time;
    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) return -1.0; // Indicate error
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance data to a file
void log_data(float distance) {
    if (distance < 0) {
        fprintf(log_file, "Error: Invalid distance reading\n");
    } else if (distance > MAX_DISTANCE) {
        fprintf(log_file, "Error: Distance out of range (%.2f cm)\n", distance);
    } else {
        fprintf(log_file, "%.2f cm\n", distance);
    }
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the pulse duration
        long pulse_duration = pulse_in(ECHO_PIN, 1, TIMEOUT_US);

        // Calculate the distance
        float distance = calculate_distance(pulse_duration);

        // Log the data
        log_data(distance);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100 ms
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

