#define MQTT_TOPIC "device_readings"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define READ_INTERVAL_MS 5000 // 5 seconds

// Sensor readings
#define ADC_CHANNEL 0 // MCP3008 channel for analog input

// Global variables
static volatile int keepRunning = 1;
static struct mosquitto *mosq = NULL;
static int spi_fd;

// Function prototypes
int read_mcp3008(int channel);
