// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3.3;
}

// Function to convert voltage to temperature (Celsius)
float voltage_to_temperature(float voltage) {
    // Assuming a linear relationship between voltage and temperature
    // You'll need to calibrate this based on your specific sensor
    return voltage * 100.0; // Example: 1V = 100°C
}

// Function to publish temperature reading to MQTT
int publish_mqtt(float temperature) {
    char payload[50];
    int ret;

    snprintf(payload, sizeof(payload), "%.2f", temperature);

    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keepRunning = 0;
}

// MQTT setup function
int setup_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_loop_start(mosq);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error starting MQTT loop: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// MQTT cleanup function
void cleanup_mqtt() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
}

int main() {
    int adc_value;
    float voltage, temperature;
    int retry;

    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI.\n");
        return 1;
    }

    // Setup MQTT
    if (setup_mqtt() != 0) {
        fprintf(stderr, "Error setting up MQTT.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting temperature monitoring...\n");

    while (keepRunning) {
        // Read ADC value
        adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value.\n");
            retry = 0;
            while (retry < RETRY_COUNT) {
                fprintf(stderr, "Retrying ADC read... (%d/%d)\n", retry + 1, RETRY_COUNT);
                delay(RETRY_DELAY_MS);
                adc_value = read_mcp3008(ADC_CHANNEL);
                if (adc_value != -1) break;
                retry++;
            }
            if (retry == RETRY_COUNT) {
                fprintf(stderr, "Failed to read ADC after multiple retries.\n");
                continue; // Skip to the next iteration
            }
            continue; // Skip to the next iteration after retry
        }

        // Convert ADC value to voltage
        voltage = adc_to_voltage(adc_value);

        // Convert voltage to temperature
        temperature = voltage_to_temperature(voltage);

        // Publish temperature reading to MQTT
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (publish_mqtt(temperature) == 0) {
                break;
            } else {
                fprintf(stderr, "Error publishing MQTT message, retrying... (%d/%d)\n", retry + 1, RETRY_COUNT);
                delay(RETRY_DELAY_MS);
                retry++;
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to publish MQTT after multiple retries.\n");
        }

        // Wait for the next reading
        delay(READ_INTERVAL_MS);
    }

    // Cleanup
    cleanup_mqtt();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

