#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_SEC 5

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = POLL_INTERVAL_SEC;
    sleep_time.tv_nsec = 0;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Print GPIO value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep for POLL_INTERVAL_SEC seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
    }

    printf("Exiting cleanly.\n");
    return 0;
}

