#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <mqtt.h>

// MQTT Broker details
#define MQTT_BROKER "tcp://localhost:1883" // Replace with your broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/temperature"

// I2C address of the temperature sensor
#define TEMP_SENSOR_ADDR 0x48

// Global variables
static volatile int keepRunning = 1 ;
static int i2c_fd ;

// Signal handler for Ctrl+C
static void mySigIntHandler (int signum)
{
  keepRunning = 0 ;
  printf ("\nExiting...\n") ;
}

// Function to read the temperature from the I2C device
static int readTemperature (int fd)
{
  int temp ;

  temp = wiringPiI2CReadReg16 (fd, 0x00) ;
  if (temp < 0)
  {
    fprintf (stderr, "Error reading temperature: %s\n", strerror (errno)) ;
    return -1 ;
  }

  // Convert to Celsius
  temp = temp / 10 ;
  return temp ;
}

// Function to publish the temperature to MQTT
static int publishTemperature (const char *topic, int temp)
{
  int rc ;

  rc = mqtt_publish (topic, temp) ;
  if (rc != 0)
  {
    fprintf (stderr, "Error publishing temperature: %s\n", strerror (errno)) ;
    return -1 ;
  }

  return 0 ;
}

int main (void)
{
  int temp ;
  int rc ;

  // Set up signal handler for Ctrl+C
  signal (SIGINT, mySigIntHandler) ;

  // Initialize wiringPi
  if (wiringPiSetup () == -1)
  {
    fprintf (stderr, "wiringPiSetup failed: %s\n", strerror (errno)) ;
    return 1 ;
  }

  // Initialize I2C
  i2c_fd = wiringPiI2CSetup (TEMP_SENSOR_ADDR) ;
  if (i2c_fd == -1)
  {
    fprintf (stderr, "wiringPiI2CSetup failed: %s\n", strerror (errno)) ;
    return 1 ;
  }

  // Initialize MQTT
  rc = mqtt_init (MQTT_BROKER, MQTT_PORT) ;
  if (rc != 0)
  {
    fprintf (stderr, "mqtt_init failed: %s\n", strerror (errno)) ;
    return 1 ;
  }

  printf ("Sensor program started\n") ;

  // Main loop
  while (keepRunning)
  {
    // Read temperature
    temp = readTemperature (i2c_fd) ;

    if (temp != -1)
    {
      // Publish temperature
      if (publishTemperature (MQTT_TOPIC, temp) != 0)
      {
        fprintf (stderr, "Failed to publish temperature\n") ;
      }
      else
      {
        printf ("Published temperature: %d\n", temp) ;
      }
    }
    else
    {
      fprintf (stderr, "Failed to read temperature\n") ;
    }

    delay (1000) ;
  }

  // Clean up
  mqtt_destroy () ;
  printf ("Sensor program finished\n") ;

  return 0 ;
}

