#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define GPIO pins
#define GPIO_PWM1 2
#define GPIO_PWM2 3
#define GPIO_PWM3 18
#define GPIO_PWM4 23
#define GPIO_PWM5 24

// Define I2C address of BH1750
#define BH1750_ADDR 0x23

// Define PWM frequency
#define PWM_FREQ 1000

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_i2c();
void cleanup_gpio();
void cleanup_i2c();
void set_pwm_duty_cycle(int gpio, int duty_cycle);
int read_bh1750();

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int init_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PWM1, PI_OUTPUT);
    gpioSetMode(GPIO_PWM2, PI_OUTPUT);
    gpioSetMode(GPIO_PWM3, PI_OUTPUT);
    gpioSetMode(GPIO_PWM4, PI_OUTPUT);
    gpioSetMode(GPIO_PWM5, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_PWM1, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_PWM2, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_PWM3, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_PWM4, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_PWM5, PWM_FREQ);

    return 0;
}

// Initialize I2C communication
int init_i2c()
{
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-1");

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %s\n", filename);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0)
    {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave.\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio()
{
    gpioPWM(GPIO_PWM1, 0);
    gpioPWM(GPIO_PWM2, 0);
    gpioPWM(GPIO_PWM3, 0);
    gpioPWM(GPIO_PWM4, 0);
    gpioPWM(GPIO_PWM5, 0);

    gpioTerminate();
}

// Cleanup I2C communication
void cleanup_i2c()
{
    if (i2c_fd != -1)
    {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    int range = 1000; // PWM range
    int duty_cycle_value = (int)(((float)duty_cycle / 100.0) * range);

    gpioPWM(gpio, duty_cycle_value);
}

// Read light intensity from BH1750
int read_bh1750()
{
    unsigned char buf[2];
    int lux = -1;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // Continuous H-resolution mode
    if (write(i2c_fd, buf, 1) != 1)
    {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2)
    {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    // Convert data to lux
    lux = (buf[0] << 8) | buf[1];
    lux /= 1.2; // BH1750 datasheet

    return lux;
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0)
    {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0)
    {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running)
    {
        // Read light intensity
        int lux = read_bh1750();
        if (lux >= 0)
        {
            printf("Lux: %d\n", lux);

            // Set PWM duty cycle based on lux value
            if (lux < 100)
            {
                set_pwm_duty_cycle(GPIO_PWM1, 0);
                set_pwm_duty_cycle(GPIO_PWM2, 0);
                set_pwm_duty_cycle(GPIO_PWM3, 0);
                set_pwm_duty_cycle(GPIO_PWM4, 0);
                set_pwm_duty_cycle(GPIO_PWM5, 0);
            }
            else if (lux < 200)
            {
                set_pwm_duty_cycle(GPIO_PWM1, 50);
                set_pwm_duty_cycle(GPIO_PWM2, 50);
                set_pwm_duty_cycle(GPIO_PWM3, 50);
                set_pwm_duty_cycle(GPIO_PWM4, 50);
                set_pwm_duty_cycle(GPIO_PWM5, 50);
            }
            else if (lux < 300)
            {
                set_pwm_duty_cycle(GPIO_PWM1, 75);
                set_pwm_duty_cycle(GPIO_PWM2, 75);
                set_pwm_duty_cycle(GPIO_PWM3, 75);
                set_pwm_duty_cycle(GPIO_PWM4, 75);
                set_pwm_duty_cycle(GPIO_PWM5, 75);
            }
            else
            {
                set_pwm_duty_cycle(GPIO_PWM1, 100);
                set_pwm_duty_cycle(GPIO_PWM2, 100);
                set_pwm_duty_cycle(GPIO_PWM3, 100);
                set_pwm_duty_cycle(GPIO_PWM4, 100);
                set_pwm_duty_cycle(GPIO_PWM5, 100);
            }
        }
        else
        {
            fprintf(stderr, "Failed to read lux value\n");
        }

        usleep(100000); // 100ms
    }

    // Cleanup
    cleanup_gpio();
    cleanup_i2c();

    return 0;
}

