#define GPIO_CHIP "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3

struct gpiod_chip *chip;
struct gpiod_line *line2, *line3;
volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get line handles for GPIO 2 and GPIO 3
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_2);
        gpiod_chip_close(chip);
        return 1;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line2, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", GPIO_2);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line3, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 2 to HIGH
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Error: Could not set value for line %d\n", GPIO_2);
            break;
        }

        // Set GPIO 3 to LOW
        if (gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Error: Could not set value for line %d\n", GPIO_3);
            break;
        }

        // Print current state
        printf("GPIO 2: HIGH, GPIO 3: LOW\n");

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 0;
}

