// Define GPIO chip and line
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE "gpio4"

// Global variables for GPIO lines
struct gpiod_line *data_line = NULL;
struct gpiod_line *clock_line = NULL;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    data_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!data_line) {
        perror("Error getting data line");
        gpiod_chip_close(chip);
        return -1;
    }

    clock_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!clock_line) {
        perror("Error getting clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request data line for input
    if (gpiod_line_request_input(data_line, "dht22_data") < 0) {
        perror("Error requesting data line for input");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request clock line for output
    if (gpiod_line_request_output(clock_line, "dht22_clock", 0) < 0) {
        perror("Error requesting clock line for output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to release GPIO lines
void release_gpio()
{
    if (data_line) {
        gpiod_line_release(data_line);
        data_line = NULL;
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
        clock_line = NULL;
    }
    if (data_line && clock_line) {
        gpiod_chip_close(gpiod_chip_open_by_name(GPIO_CHIP));
    }
}

