// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_line *line = NULL;
    int ret;

    if (pin == GPIO_17) {
        line = gpiod_chip_get_line(chip, pin);
    } else if (pin == GPIO_23) {
        line = gpiod_chip_get_line(chip, pin);
    } else if (pin == GPIO_24) {
        line = gpiod_chip_get_line(chip, pin);
    } else if (pin == GPIO_25) {
        line = gpiod_chip_get_line(chip, pin);
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", pin);
        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %s\n", pin, gpiod_line_request_output_error(line));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to unexport a GPIO pin
