        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", pin);
        return -1;
    }

    ret = gpiod_line_release(line);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not release GPIO %d: %s\n", pin, gpiod_line_release_error(line));
        return -1;
    }

    return 0;
}

