#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor"
#define MQTT_KEEPALIVE 60

// Global variables
static volatile int keepRunning = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
int publish_mqtt(const char *message);
void signal_handler(int sig);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to publish MQTT message
int publish_mqtt(const char *message) {
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keepRunning = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    wiringPiSPIClose(SPI_CHANNEL);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed\n");
        return 1;
    }

    // Initialize SPI
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPiSPISetup failed\n");
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_loop_callback_set(mosq, NULL);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keepRunning) {
        // Read sensor data
        int adc_value = read_mcp3008(0); // Read from channel 0
        char message[50];
        snprintf(message, sizeof(message), "ADC Value: %d", adc_value);

        // Publish MQTT message
        if (publish_mqtt(message) != 0) {
            fprintf(stderr, "Failed to publish MQTT message\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <string.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480

int main() {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Error opening device");
        return 1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return 1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Use MJPEG format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return 1;
    }

    // Capture image
    char buffer[IMAGE_WIDTH * IMAGE_HEIGHT];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
    if (bytes_read < 0) {
        perror("Error reading image");
        close(fd);
        return 1;
    }

    // Save image to file
    FILE *fp = fopen("captured_image.mjpg", "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        close(fd);
        return 1;
    }
    fwrite(buffer, 1, bytes_read, fp);
    fclose(fp);

    close(fd);
    printf("Image captured and saved to captured_image.mjpg\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM control
#define PWM1_PIN 4
#define PWM2_PIN 5
#define PWM3_PIN 6
#define PWM4_PIN 7
#define PWM5_PIN 8
#define PWM6_PIN 9

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM frequency and range
void set_pwm_frequency(int pin, int frequency, int range)
{
    gpioSetPWMfrequency(pin, frequency);
    gpioSetPWMrange(pin, range);
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int pin, int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    gpioPWM(pin, duty_cycle);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set PWM frequency and range for each pin
    set_pwm_frequency(PWM1_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM2_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM3_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM4_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM5_PIN, PWM_FREQUENCY, PWM_RANGE);
    set_pwm_frequency(PWM6_PIN, PWM_FREQUENCY, PWM_RANGE);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle for each pin
        set_pwm_duty_cycle(PWM1_PIN, 128); // 50% duty cycle
        set_pwm_duty_cycle(PWM2_PIN, 128);
        set_pwm_duty_cycle(PWM3_PIN, 128);
        set_pwm_duty_cycle(PWM4_PIN, 128);
        set_pwm_duty_cycle(PWM5_PIN, 128);
        set_pwm_duty_cycle(PWM6_PIN, 128);

        // Print the state of each pin to standard output
        printf("GPIO %d: %d\n", PWM1_PIN, gpioGetPWMdutycycle(PWM1_PIN));
        printf("GPIO %d: %d\n", PWM2_PIN, gpioGetPWMdutycycle(PWM2_PIN));
        printf("GPIO %d: %d\n", PWM3_PIN, gpioGetPWMdutycycle(PWM3_PIN));
        printf("GPIO %d: %d\n", PWM4_PIN, gpioGetPWMdutycycle(PWM4_PIN));
        printf("GPIO %d: %d\n", PWM5_PIN, gpioGetPWMdutycycle(PWM5_PIN));
        printf("GPIO %d: %d\n", PWM6_PIN, gpioGetPWMdutycycle(PWM6_PIN));

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM output on all pins
    set_pwm_duty_cycle(PWM1_PIN, 0);
    set_pwm_duty_cycle(PWM2_PIN, 0);
    set_pwm_duty_cycle(PWM3_PIN, 0);
    set_pwm_duty_cycle(PWM4_PIN, 0);
    set_pwm_duty_cycle(PWM5_PIN, 0);
    set_pwm_duty_cycle(PWM6_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

