// Export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "gpio_export", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Set GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_direction(line, direction) < 0) {
        perror("Error setting GPIO direction");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Set GPIO value (0 or 1)
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Get GPIO value (0 or 1)
int gpio_get_value(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    gpiod_chip_close(chip);
    gpiod_line_release(line);
    return value;
}

