    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Export GPIO pins
    if (gpio_export(GPIO17) < 0 || gpio_export(GPIO18) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO17, "out") < 0 || gpio_set_direction(GPIO18, "out") < 0) {
