#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for graceful exit
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO high
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO value high");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_PIN);

        // Sleep for a short interval
        nanosleep(&sleep_time, NULL);

        // Set GPIO low
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO value low");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_PIN);

        // Sleep for a short interval
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("Error closing GPIO chip");
    }

    printf("Exiting cleanly.\n");
    return 0;
}

