#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 10

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Could not read GPIO line %d\n", GPIO_PIN);
            break;
        }

        // Print the state
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

