    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to initialize GPIO pins
void gpio_init(void)
{
    wiringPiSetupGpio(); // Use BCM GPIO numbering
    pinMode(GPIO17, OUTPUT);
    pinMode(GPIO18, OUTPUT);
    pinMode(GPIO24, OUTPUT);
}

// Function to write a value to a GPIO pin
void gpio_write(int pin, int value)
{
    digitalWrite(pin, value);
}

// Function to cleanup GPIO pins
void gpio_cleanup(void)
{
    gpio_write(GPIO17, LOW);
    gpio_write(GPIO18, LOW);
    gpio_write(GPIO24, LOW);
}

// Function to initialize GPIO pins
void cleanup(void)
{
    gpio_cleanup();
    close(spi_fd);
}

// Function to handle errors
void error_exit(const char *message)
{
    fprintf(stderr, "Error: %s\n", message);
    cleanup();
    exit(EXIT_FAILURE);
}

int main(void)
{
    // Initialize SPI
    if (spi_init() < 0)
    {
        error_exit("SPI initialization failed");
    }

    // Initialize GPIO pins
    gpio_init();

    // Main loop
    while (1)
    {
        // Read ADC value from MCP3008
        int adc_value = spi_read(MCP3008_CHANNEL);

        if (adc_value < 0)
        {
            fprintf(stderr, "Error reading ADC value\n");
        }
        else
        {
            // Convert ADC value to GPIO state
            int gpio_state = (adc_value > 500) ? HIGH : LOW;

            // Write GPIO state to GPIO pins
            gpio_write(GPIO17, gpio_state);
            gpio_write(GPIO18, gpio_state);
            gpio_write(GPIO24, gpio_state);

            // Print GPIO state to standard output
            printf("GPIO17: %d, GPIO18: %d, GPIO24: %d\n", gpio_state, gpio_state, gpio_state);
        }

        // Delay for 1 second
        delay(1000);
    }

    return 0;
}

#include <stdio.h>
