#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_BUFFER_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2) // RGB24

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

buffer *buffers = NULL;
static int n_buffers = 0;
static int fd = -1;
static int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    running = 0;
}

// Function to initialize the camera device
int init_camera()
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB24; // Request RGB24 format
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return -1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return -1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return -1;
        }
    }

    return 0;
}

// Function to capture an image
int capture_image(int fd, int buffer_index)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer_index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    enum v4l2_buf_type type2 = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type2) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to save the captured image to a file
int save_image(const char *filename, const void *buffer, size_t size)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file");
        return -1;
    }

    size_t written = fwrite(buffer, 1, size, fp);
    if (written != size) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to cleanup resources
void cleanup()
{
    if (buffers) {
        for (int i = 0; i < n_buffers; i++) {
            if (munmap(buffers[i].start, buffers[i].length) < 0) {
                perror("Error unmapping buffer");
            }
        }
        free(buffers);
    }
    if (fd != -1) {
        close(fd);
    }
}

int main()
{
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (init_camera() < 0) {
        fprintf(stderr, "Camera initialization failed\n");
        return 1;
    }

    // Main loop
    while (running) {
        gettimeofday(&tv, NULL);
        tm_info = localtime(&tv.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03d", (int)(tv.tv_usec / 1000));

        if (capture_image(fd, 0) == 0) {
            if (save_image(timestamp, buffers[0].start, IMAGE_BUFFER_SIZE) == 0) {
                printf("Image saved to %s\n", timestamp);
            } else {
                fprintf(stderr, "Failed to save image\n");
            }
        } else {
            fprintf(stderr, "Failed to capture image\n");
        }

        sleep(0.1);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

