#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x40
#define PCF8574_REG 0x00

int main() {
    int fd;
    unsigned char data[8];
    int i;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Set PCF8574 to output mode
    data[0] = 0x00; // Output mode
    if (write(fd, data, 1) != 1) {
        perror("Failed to set output mode");
        close(fd);
        return 1;
    }

    // Display values
    for (i = 0; i < 8; i++) {
        data[i] = i; // Display values 0-7
        if (write(fd, data, 1) != 1) {
            perror("Failed to write to I2C device");
            close(fd);
            return 1;
        }
        usleep(50000); // 50ms delay
    }

    close(fd);
    return 0;
}

