#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define the maximum distance the sensor can measure (in cm)
#define MAX_DISTANCE 400

// Define the timeout for the echo pin (in microseconds)
#define TIMEOUT 50000

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Flag to indicate if the program should exit
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the GPIO lines
int initialize_gpio()
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line as output
    if (gpiod_line_request_output(trigger_line, "distance_sensor", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    if (gpiod_line_request_input(echo_line, "distance_sensor") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor()
{
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
    }
    usleep(10); // 10 us pulse
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
    }
}

// Function to measure the echo pulse width
long measure_pulse_width()
{
    struct timespec start, end;
    long pulse_width = 0;

    // Wait for the echo line to go high
    while (gpiod_line_get_value(echo_line) == 0 && program_running) {
        clock_gettime(CLOCK_MONOTONIC, &start);
    }

    if (!program_running) return -1; // Exit if signal received

    // Wait for the echo line to go low
    while (gpiod_line_get_value(echo_line) == 1 && program_running) {
        clock_gettime(CLOCK_MONOTONIC, &end);
    }

    if (!program_running) return -1; // Exit if signal received

    // Calculate the pulse width in microseconds
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width)
{
    if (pulse_width < 0) return -1.0; // Indicate error
    return (pulse_width / 1000000.0) * MAX_DISTANCE;
}

// Function to print the distance to standard output
void print_distance(float distance)
{
    if (distance < 0) {
        fprintf(stderr, "Error: Invalid distance reading.\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Distance sensor initialized. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);
        print_distance(distance);
        usleep(50000); // 50 ms delay
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
