#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23
#define POLL_INTERVAL_MS 5000

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("Caught signal, exiting...\n");
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Digital output on GPIO %d (BCM %d) - Requested\n", GPIO_PIN, GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO value");
            break; // Exit loop on error
        }

        // Print the value
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        // Sleep
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("Error closing GPIO chip");
    }

    printf("Exiting cleanly.\n");
    return 0;
}

