        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        if (i2c_read_word(fd, MPU6050_ACCEL_XOUT_H, &accel_x) < 0) {
            fprintf(stderr, "Error reading accelerometer X, retrying...\n");
            close(fd);
            return 1;
        }
        if (i2c_read_word(fd, MPU6050_ACCEL_XOUT_H + 2, &accel_y) < 0) {
            fprintf(stderr, "Error reading accelerometer Y, retrying...\n");
            close(fd);
