// Function to write a command to the SHT31
int sht31_write_command(int fd, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write command to SHT31");
        return -1;
    }
    return 0;
}

// Function to read data from the SHT31
int sht31_read_data(int fd, uint8_t *data, int len) {
    if (write(fd, "\0", 1) != 1) {
        perror("Failed to write null byte to I2C device");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("Failed to read data from SHT31");
        return -1;
    }
    return 0;
}

// Function to calculate CRC checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT31
int sht31_read(int fd, float *temperature, float *humidity) {
    uint8_t data[6];
    uint16_t raw_temperature, raw_humidity;
    uint8_t crc_temperature, crc_humidity;

    // Send measurement command
    if (sht31_write_command(fd, SHT31_MEASURE_CMD) != 0) {
        return -1;
    }

    // Wait for measurement to complete (typical conversion time is 10ms, but let's wait 20ms)
    usleep(20000); // 20ms

    // Read 6 bytes of data
    if (sht31_read_data(fd, data, 6) != 0) {
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

