// Function prototypes
void signal_handler(int signal);
int init_gpio(void);
int init_i2c(void);
void cleanup_gpio(int signum);
void cleanup_i2c(int signum);
void set_pwm_duty_cycle(int gpio, int duty_cycle);
void set_pwm_frequency(int gpio, int frequency);
void set_pwm_range(int gpio, int range);
void set_pwm_mode(int gpio, int mode);

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO
int init_gpio(void)
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PWM1_GPIO, PI_OUTPUT);
    gpioSetMode(PWM2_GPIO, PI_OUTPUT);
    gpioSetMode(PWM3_GPIO, PI_OUTPUT);
    gpioSetMode(PWM4_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(PWM1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM4_GPIO, PWM_FREQUENCY);

    gpioSetPWMrange(PWM1_GPIO, PWM_RANGE);
    gpioSetPWMrange(PWM2_GPIO, PWM_RANGE);
    gpioSetPWMrange(PWM3_GPIO, PWM_RANGE);
    gpioSetPWMrange(PWM4_GPIO, PWM_RANGE);

    gpioSetPWMmode(PWM1_GPIO, PI_PWM_MODE_MS);
    gpioSetPWMmode(PWM2_GPIO, PI_PWM_MODE_MS);
    gpioSetPWMmode(PWM3_GPIO, PI_PWM_MODE_MS);
    gpioSetPWMmode(PWM4_GPIO, PI_PWM_MODE_MS);

    return 0;
}

// Initialize I2C
int init_i2c(void)
{
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0)
    {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(int signum)
{
    gpioPWM(PWM1_GPIO, 0);
    gpioPWM(PWM2_GPIO, 0);
    gpioPWM(PWM3_GPIO, 0);
    gpioPWM(PWM4_GPIO, 0);

    gpioTerminate();
    printf("GPIO cleanup done.\n");
    exit(0);
}

// Cleanup I2C
void cleanup_i2c(int signum)
{
    if (i2c_fd != -1)
    {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("I2C cleanup done.\n");
}

// Set PWM duty cycle
void set_pwm_duty_cycle(int gpio, int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000) duty_cycle = 1000;
    gpioPWM(gpio, duty_cycle);
}

// Set PWM frequency
void set_pwm_frequency(int gpio, int frequency)
{
    if (frequency > 0) gpioSetPWMfrequency(gpio, frequency);
}

// Set PWM range
void set_pwm_range(int gpio, int range)
{
    if (range > 0) gpioSetPWMrange(gpio, range);
}

// Set PWM mode
void set_pwm_mode(int gpio, int mode)
{
    if (mode == PI_PWM_MODE_MS) gpioSetPWMmode(gpio, PI_PWM_MODE_MS);
}

int main(void)
{
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0)
    {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0)
    {
        fprintf(stderr, "I2C initialization failed, exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running)
    {
        // Set PWM duty cycle
        set_pwm_duty_cycle(PWM1_GPIO, 500);
        set_pwm_duty_cycle(PWM2_GPIO, 750);
        set_pwm_duty_cycle(PWM3_GPIO, 250);
        set_pwm_duty_cycle(PWM4_GPIO, 875);

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup
    cleanup_gpio(0);

    return 0;
}

