    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", GPIO_2);
        gpiod_chip_close(chip);
        return 1;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

