#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2 // BCM GPIO 2, Physical GPIO 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000000; // 1 second

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (keep_running) {
        // Set GPIO state to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value");
            break; // Exit loop on error
        }

        // Print state to stdout
        printf("GPIO %d: HIGH\n", GPIO_PIN);

        // Sleep for 60 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
    }

    printf("Exiting cleanly.\n");
    return 0;
}

