    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Export GPIO pins
    if (gpio_export(GPIO_2) < 0 || gpio_export(GPIO_3) < 0 || gpio_export(GPIO_17) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    // Set GPIO directions to output
    if (gpio_set_direction(GPIO_2, "out") < 0 || gpio_set_direction(GPIO_3, "out") < 0 || gpio_set_direction(GPIO_17, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO directions. Exiting.\n");
        cleanup(0); // Call cleanup before exiting
        return 1;
    }

    // Main loop
    for (int i = 0; i < 3; i++) {
        // Cycle 1
        printf("Cycle 1:\n");
        gpio_set_value(GPIO_2, 1);
        gpio_set_value(GPIO_3, 0);
        gpio_set_value(GPIO_17, 1);
        sleep(1);
        gpio_set_value(GPIO_2, 0);
        gpio_set_value(GPIO_3, 1);
        gpio_set_value(GPIO_17, 0);
        sleep(1);

        // Cycle 2
        printf("\nCycle 2:\n");
        gpio_set_value(GPIO_2, 1);
        gpio_set_value(GPIO_3, 1);
        gpio_set_value(GPIO_17, 0);
        sleep(1);
        gpio_set_value(GPIO_2, 0);
        gpio_set_value(GPIO_3, 0);
        gpio_set_value(GPIO_17, 1);
        sleep(1);

        // Cycle 3
        printf("\nCycle 3:\n");
        gpio_set_value(GPIO_2, 0);
        gpio_set_value(GPIO_3, 0);
        gpio_set_value(GPIO_17, 0);
        sleep(1);
        gpio_set_value(GPIO_2, 1);
        gpio_set_value(GPIO_3, 1);
        gpio_set_value(GPIO_17, 1);
        sleep(1);
    }

    // Cleanup and exit
    cleanup(0);
    return 0;
}

