{
    int adc_value;
    FILE *fp;
    char log_message[256];

    // Initialize syslog
    openlog("gpio_control", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1)
    {
        syslog(LOG_ERR, "Failed to initialize wiringPi: %s", strerror(errno));
        return 1;
