            if (adc_value < 512)
            {
                set_gpio_output(GPIO_PIN, LOW);
            }
            else
            {
                set_gpio_output(GPIO_PIN, HIGH);
            }

            // Log the state
            snprintf(log_message, sizeof(log_message), "ADC Value: %d, GPIO State: %s", adc_value, (digitalRead(GPIO_PIN) == LOW) ? "LOW" : "HIGH");
            syslog(LOG_INFO, "%s", log_message);
        }
        else
        {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        sleep(1);
    }

    // Clean up and exit
    syslog(LOG_INFO, "GPIO control program exiting");
    set_gpio_output(GPIO_PIN, LOW); // Set to LOW before exiting
    bcm2835_close();
    closelog();

    return 0;
}

