#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18 // BCM GPIO 18, Physical GPIO 12

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int main()
{
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 0.01 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get a line for the GPIO pin
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output\n", GPIO_PIN);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Set the GPIO pin to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to HIGH\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Print the state
        printf("GPIO %d: HIGH\n", GPIO_PIN);

        // Sleep for 0.01 seconds
        nanosleep(&sleep_time, NULL);

        // Set the GPIO pin to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error: Could not set GPIO %d to LOW\n", GPIO_PIN);
            break; // Exit loop on error
        }

        // Print the state
        printf("GPIO %d: LOW\n", GPIO_PIN);

        // Sleep for 0.01 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release the line
    if (line) {
        gpiod_line_release(line);
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

