    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO pin to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Error setting GPIO line value");
            break; // Exit loop on error
        }

        // Print HIGH
        printf("HIGH\n");

        // Sleep for a short interval
        nanosleep(&sleep_time, NULL);

        // Set GPIO pin to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Error setting GPIO line value");
            break; // Exit loop on error
        }

        // Print LOW
        printf("LOW\n");

        // Sleep for a short interval
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the RGB LED strip
#define RED_PIN   18
#define GREEN_PIN 23
#define BLUE_PIN  24

// Define the number of LEDs in the strip
#define NUM_LEDS 10

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the color of a single LED
void set_led_color(int gpio, int red, int green, int blue)
{
    gpioPWM(gpio, red);
    gpioPWM(gpio + 1, green);
    gpioPWM(gpio + 2, blue);
}

// Function to set the color of all LEDs in the strip
void set_strip_color(int red, int green, int blue)
{
    for (int i = 0; i < NUM_LEDS; i++)
    {
        set_led_color(RED_PIN + i, red, green, blue);
    }
}

int main()
{
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
