    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance >= 0 && distance <= 400) { // Validate distance
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Timeout waiting for echo\n");
        }

        gpioDelay(100); // Delay between measurements
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DURATION_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec req = {0, DURATION_MS * 1000000L};
    int ret;

    // Register signal handler for graceful exit
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request line for output
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    printf("Digital output on GPIO %d (BCM %d) - Requested for output\n", GPIO_PIN, GPIO_PIN);

    // Main loop
    for (int i = 0; i < 10; ++i) {
        // Set GPIO high
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break; // Exit loop on error
        }
        printf("GPIO %d (BCM %d) - HIGH\n", GPIO_PIN, GPIO_PIN);
        nanosleep(&req, NULL);

        // Set GPIO low
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (LOW)");
            break; // Exit loop on error
        }
        printf("GPIO %d (BCM %d) - LOW\n", GPIO_PIN, GPIO_PIN);
        nanosleep(&req, NULL);
    }

    // Release line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting cleanly.\n");
    return 0;
}

