    terminate = 1;
}

int main() {
    int duty_cycle;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    result = gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set PWM duty cycle
    result = gpioPWM(PWM_GPIO, 0); // Initially off
    if (result != 0) {
        fprintf(stderr, "Failed to set initial PWM duty cycle: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Driving PWM on GPIO %d. Press Ctrl+C to exit.\n", PWM_GPIO);

