void cleanup_lines();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Initialize GPIO lines
int initialize_gpio() {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", CHIP_NAME);
        return -1;
    }

    for (int i = 0; i < num_lines; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_names[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Could not get line %s\n", line_names[i]);
            cleanup_gpio();
            return -1;
        }

        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Error: Could not request line %s as output\n", line_names[i]);
            cleanup_gpio();
            return -1;
        }
    }
    return 0;
}

// Cleanup GPIO lines
void cleanup_lines() {
    for (int i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i]);
    }
}

// Set GPIO value
void set_gpio_value(int gpio, int value) {
    if (lines[gpio - 4] == NULL) {
        fprintf(stderr, "Error: GPIO %d not initialized\n", gpio);
        return;
    }
    if (gpiod_line_set_value(lines[gpio - 4], value) < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO %d\n", gpio);
    }
}

// Report current state
void report_state() {
    printf("GPIO 4: %s\n", (gpiod_line_get_value(lines[0]) == 0) ? "OFF" : "ON");
    printf("GPIO 17: %s\n", (gpiod_line_get_value(lines[1]) == 0) ? "OFF" : "ON");
    printf("GPIO 22: %s\n", (gpiod_line_get_value(lines[2]) == 0) ? "OFF" : "ON");
    printf("GPIO 23: %s\n", (gpiod_line_get_value(lines[3]) == 0) ? "OFF" : "ON");
    printf("GPIO 24: %s\n", (gpiod_line_get_value(lines[4]) == 0) ? "OFF" : "ON");
    printf("GPIO 25: %s\n", (gpiod_line_get_value(lines[5]) == 0) ? "OFF" : "ON");
    printf("GPIO 27: %s\n", (gpiod_line_get_value(lines[6]) == 0) ? "OFF" : "ON");
    printf("\n");
}

// Cleanup GPIO resources
void cleanup_gpio() {
    for (int i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i]);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    for (int i = 0; i < 100 && program_running; i++) {
        for (int j = 0; j < num_lines; j++) {
            set_gpio_value(j + 4, 1); // Set HIGH
            report_state();
            sleep(0.5);
            set_gpio_value(j + 4, 0); // Set LOW
            report_state();
        }
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

