#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_27 27

struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line27;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("Error getting GPIO 27 line");
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line27, "digital_output", 0) < 0) {
        perror("Error requesting GPIO 27 as output");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 17 to HIGH
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }

        // Set GPIO 27 to LOW
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("Error setting GPIO 27 value");
            break;
        }

        // Print the state
        printf("GPIO 17: HIGH, GPIO 27: LOW\n");

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line17);
    gpiod_line_release(line27);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM control
#define PWM1_PIN 17
#define PWM2_PIN 18
#define PWM3_PIN 22
#define PWM4_PIN 23
#define PWM5_PIN 24
#define PWM6_PIN 25

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM duty cycle on a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle)
{
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE)
    {
        fprintf(stderr, "Error: Duty cycle out of range (0-%d). Setting to 0.\n", PWM_RANGE);
        duty_cycle = 0;
    }

    gpioPWM(gpio_pin, duty_cycle);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM1_PIN, PI_OUTPUT);
    gpioSetMode(PWM2_PIN, PI_OUTPUT);
    gpioSetMode(PWM3_PIN, PI_OUTPUT);
    gpioSetMode(PWM4_PIN, PI_OUTPUT);
    gpioSetMode(PWM5_PIN, PI_OUTPUT);
    gpioSetMode(PWM6_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM5_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM6_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(PWM1_PIN, PWM_RANGE);
    gpioSetPWMrange(PWM2_PIN, PWM_RANGE);
    gpioSetPWMrange(PWM3_PIN, PWM_RANGE);
    gpioSetPWMrange(PWM4_PIN, PWM_RANGE);
    gpioSetPWMrange(PWM5_PIN, PWM_RANGE);
    gpioSetPWMrange(PWM6_PIN, PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycles
        set_pwm_duty_cycle(PWM1_PIN, 128); // 50%
        set_pwm_duty_cycle(PWM2_PIN, 128); // 50%
        set_pwm_duty_cycle(PWM3_PIN, 128); // 50%
        set_pwm_duty_cycle(PWM4_PIN, 128); // 50%
        set_pwm_duty_cycle(PWM5_PIN, 128); // 50%
        set_pwm_duty_cycle(PWM6_PIN, 128); // 50%

        // Print PWM state to standard output
        printf("PWM1: %d, PWM2: %d, PWM3: %d, PWM4: %d, PWM5: %d, PWM6: %d\n",
               gpioGetPWMdutycycle(PWM1_PIN),
               gpioGetPWMdutycycle(PWM2_PIN),
               gpioGetPWMdutycycle(PWM3_PIN),
               gpioGetPWMdutycycle(PWM4_PIN),
               gpioGetPWMdutycycle(PWM5_PIN),
               gpioGetPWMdutycycle(PWM6_PIN));

        // Wait for 0.05 seconds
        gpioDelay(50000); // 50000 microseconds = 0.05 seconds
    }

    // Stop PWM output
    gpioPWM(PWM1_PIN, 0);
    gpioPWM(PWM2_PIN, 0);
    gpioPWM(PWM3_PIN, 0);
    gpioPWM(PWM4_PIN, 0);
    gpioPWM(PWM5_PIN, 0);
    gpioPWM(PWM6_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

