    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
        return -1;
    }
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    if (gpiod_line_set_direction(line, direction) < 0) {
        perror("gpiod_line_set_direction");
        return -1;
    }
    return 0;
}

