    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("gpiod_chip_get_line");
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("gpiod_line_get_value");
        return -1;
    }
    return value;
}

// Cleanup function to unexport GPIO pins
