    printf("Cleaning up GPIO pins...\n");
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_release(line24);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Export GPIO pins
    if (gpio_export(GPIO_17) < 0) return 1;
    if (gpio_export(GPIO_23) < 0) return 1;
    if (gpio_export(GPIO_24) < 0) return 1;

    // Set GPIO directions to output
    if (gpio_set_direction(GPIO_17, "out") < 0) return 1;
    if (gpio_set_direction(GPIO_23, "out") < 0) return 1;
    if (gpio_set_direction(GPIO_24, "out") < 0) return 1;

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        // Set GPIO values
        gpio_set_value(GPIO_17, 1);
        gpio_set_value(GPIO_23, 0);
        gpio_set_value(GPIO_24, 1);

        // Print the state
        printf("%s - GPIO17: %d, GPIO23: %d, GPIO24: %d\n", buf, gpio_get_value(GPIO_17), gpio_get_value(GPIO_23), gpio_get_value(GPIO_24));

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT22_GPIO 4 // GPIO pin connected to DHT22 data pin (BCM numbering)

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_count = 0;
    int last_state = 1; // Assume initial state is HIGH
    int current_state = 1;
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Minimum 20ms

    gpioSetMode(gpio, PI_INPUT);

    // Wait for the DHT22 to pull the line low
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1ms
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (LOW)\n");
        return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1); // Wait 1ms
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (HIGH)\n");
        return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1ms
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "DHT22: Timeout waiting for start signal (LOW)\n");
        return -1; // Timeout
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == last_state && timeout < 100) {
            gpioDelay(1); // Wait 1ms
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for bit transition (HIGH)\n");
            return -1; // Timeout
        }

        current_state = gpioRead(gpio);
        last_state = current_state;

        if (current_state == 0) {
            data[bit_count / 8] <<= 1;
            if (timeout > 30) {
                data[bit_count / 8] |= 1;
            }
            bit_count++;
        }
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22: Checksum failure\n");
        return -2; // Checksum failure
    }

    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT22: Error reading data, retrying...\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

