        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range (0-1000 for percentage duty cycle)
    gpioSetPWMrange(PWM_PIN_1, 1000);
    gpioSetPWMrange(PWM_PIN_2, 1000);
    gpioSetPWMrange(PWM_PIN_3, 1000);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Set PWM duty cycle to 50% (500 out of 1000)
        gpioPWM(PWM_PIN_1, 500);
        gpioPWM(PWM_PIN_2, 500);
        gpioPWM(PWM_PIN_3, 500);

        // Print the state of the GPIO pins to standard output
        printf("GPIO17: %d, GPIO18: %d, GPIO27: %d\n", gpioRead(PWM_PIN_1), gpioRead(PWM_PIN_2), gpioRead(PWM_PIN_3));

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM output
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

