#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO pin to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }
        printf("GPIO %d: HIGH\n", GPIO_PIN);

        // Sleep for 0.1 seconds
        nanosleep(&sleep_time, NULL);

        // Set GPIO pin to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value (LOW)");
            break;
        }
        printf("GPIO %d: LOW\n", GPIO_PIN);

        // Sleep for 0.1 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
    }

    printf("Exiting cleanly.\n");
    return 0;
}

