#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>

// Define SPI device and speed
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz

// Define MAX31855 register addresses
#define MAX31855_REG_CONFIG 0x00
#define MAX31855_REG_TEMP 0x01
#define MAX31855_REG_FAULT 0x02
#define MAX31855_REG_FAULT_T 0x03

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize the SPI device
int spi_init(const char *device, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode to 0
    uint8_t mode = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed_val = (uint32_t)speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a register from the MAX31855
int spi_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)reg_addr,
        .rx_buf = (unsigned long)data,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    return 0;
}

// Function to write a register to the MAX31855
int spi_write_register(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)buf,
        .rx_buf = (unsigned long)buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    return 0;
}

// Function to read a 32-bit value from the MAX31855
int spi_read_32bit(int fd, uint8_t reg_addr, uint8_t *data) {
    if (spi_read_register(fd, reg_addr, data, 4) != 0) {
        return -1;
    }
    return 0;
}

// Function to read temperature from the MAX31855
float read_temperature(int fd) {
    uint8_t data[4];
    if (spi_read_32bit(fd, MAX31855_REG_TEMP, data) != 0) {
        fprintf(stderr, "Error reading temperature register\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bit
    if (data[3] & 0x01) {
        fprintf(stderr, "Temperature fault detected!\n");
        return -1000.0; // Indicate error
    }

    // Extract temperature data (signed 14-bit value)
    int16_t temp_raw = ((data[0] << 8) | data[1]) >> 2;
    float temperature = temp_raw * 0.25;

    return temperature;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("MAX31855 Temperature Reader\n");

    while (1) {
        float temperature = read_temperature(spi_fd);

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Check SPI connection.\n");
        }

        sleep(1);
    }

    return 0;
}

