#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("Digital output on GPIO %d (BCM) - Press Ctrl+C to exit\n", GPIO_PIN);

    // Main loop
    while (keep_running) {
        // Read GPIO value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO value");
            break; // Exit loop on error
        }

        // Validate reading
        if (value >= 0 && value <= 1) {
            // Set GPIO value
            if (gpiod_line_set_value(line, value) < 0) {
                perror("Error setting GPIO value");
                break; // Exit loop on error
            }

            // Print state
            printf("GPIO %d (BCM): %d\n", GPIO_PIN, value);
        } else {
            fprintf(stderr, "Invalid GPIO value: %d\n", value);
            break; // Exit loop on invalid value
        }

        // Sleep
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 100

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct gpiod_line_request_config config;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO
int init_gpio()
{
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_test";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO value
int set_gpio_value(int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO initialized. Setting GPIO %d to %d\n", GPIO_PIN, 1);

    // Main loop
    while (keep_running) {
        if (set_gpio_value(1) < 0) {
            fprintf(stderr, "Failed to set GPIO value. Exiting.\n");
            break;
        }
        sleep(1);
        if (set_gpio_value(0) < 0) {
            fprintf(stderr, "Failed to set GPIO value. Exiting.\n");
            break;
        }
        sleep(1);
    }

    // Cleanup GPIO
    cleanup_gpio();

    printf("GPIO cleanup complete. Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_TEMP_LSB 0xFB
#define BME280_REG_TEMP_XLSB 0xFC
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_PRESS_LSB 0xF8
#define BME280_REG_PRESS_XLSB 0xF9
#define BME280_REG_HUM_MSB 0xFD
#define BME280_REG_HUM_LSB 0xFE
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// Function to read a single byte from a BME280 register
int read_register(int fd, uint8_t reg_addr) {
    uint8_t buf[1];
    buf[0] = reg_addr;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to a BME280 register
int write_register(int fd, uint8_t reg_addr, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the BME280
int read_calibration_data(int fd, uint8_t *calib_data) {
    uint8_t reg_addr = BME280_REG_CALIB_00;
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address for calibration data");
        return -1;
    }
    if (read(fd, calib_data, 26) != 26) {
        perror("Failed to read calibration data");
        return -1;
    }
    return 0;
}

// Function to read raw temperature data from the BME280
int read_raw_temperature(int fd, int32_t *raw_temp) {
    uint8_t reg_addr = BME280_REG_TEMP_MSB;
    uint8_t buf[3];
    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address for raw temperature");
        return -1;
    }
    if (read(fd, buf, 3) != 3) {
        perror("Failed to read raw temperature data");
        return -1;
    }
    *raw_temp = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    return 0;
}

// Function to read raw pressure data from the BME280
int read_raw_pressure(int fd, int32_t *raw_pressure) {
    uint8_t reg_addr = BME280_REG_PRESS_MSB;
    uint8_t buf[3];
    if (write(fd, &reg_addr, 1) != 1) {
