// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure, int32_t raw_temp, uint8_t dig_P1, int32_t dig_P2, int32_t dig_P3, int32_t dig_P4, int32_t dig_P5, int32_t dig_P6, int32_t dig_P7, int32_t dig_P8, int32_t dig_P9, uint8_t dig_H1, int32_t dig_H2, uint8_t dig_H3, int32_t dig_H4, int32_t dig_H5, int8_t dig_H6, float t_fine) {
