// Function to compensate humidity
float compensate_humidity(int32_t raw_humidity, int32_t raw_temp, uint8_t dig_H1, int32_t dig_H2, uint8_t dig_H3, int32_t dig_H4, int32_t dig_H5, int8_t dig_H6, float t_fine) {
