        }

        // Compensate data
        temperature = compensate_temperature(raw_temp, (uint8_t)calib_data[1], (int32_t)calib_data[0], (int32_t)calib_data[2]);
        pressure = compensate_pressure(raw_pressure, raw_temp, (uint8_t)calib_data[3], (int32_t)calib_data[4], (int32_t)calib_data[5], (int32_t)calib_data[6], (int32_t)calib_data[7], (int32_t)calib_data[8], (int32_t)calib_data[9], (int32_t)calib_data[10], (uint8_t)calib_data[11], (int32_t)calib_data[12], (int32_t)calib_data[13], (int32_t)calib_data[14], (int32_t)calib_data[15], (int8_t)calib_data[16], (int32_t)calib_data[17], (uint8_t)calib_data[18], (int32_t)calib_data[19], (int32_t)calib_data[20]);
