#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LINE "gpio17-17"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main()
{
    int ret;
    struct gpiod_line_request_config config;

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %s: %s\n", LINE, gpiod_line_request_error_str(ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO pin HIGH
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %s value: %s\n", LINE, gpiod_line_error_str(ret));
            break;
        }

        // Print HIGH
        printf("HIGH\n");

        // Set GPIO pin LOW
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Could not set GPIO line %s value: %s\n", LINE, gpiod_line_error_str(ret));
            break;
        }

        // Print LOW
        printf("LOW\n");

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
