#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04
#define VEML7700_ALS_DATA2 0x05

// Function to write a byte to a VEML7700 register
int veml7700_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from a VEML7700 register
int veml7700_read_register(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from the VEML7700
int veml7700_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read (high byte): %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf + 1, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X (low byte): %s\n", reg, strerror(errno));
        return -1;
    }

    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    int fd;
    uint8_t config_value = 0x00; // Integration time: 100ms, Gain: 1
    uint16_t als_data;
    uint16_t als_data2;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Configure the VEML7700
    if (veml7700_write_register(fd, VEML7700_CONFIG, config_value) < 0) {
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ALS data
        if (veml7700_read_word(fd, VEML7700_ALS_DATA, &als_data) < 0) {
            fprintf(stderr, "Error reading ALS data\n");
            break;
        }

        // Read ALS data 2
        if (veml7700_read_word(fd, VEML7700_ALS_DATA2, &als_data2) < 0) {
            fprintf(stderr, "Error reading ALS data 2\n");
            break;
        }

        // Print the readings
        printf("ALS Data: %u, ALS Data 2: %u\n", als_data, als_data2);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Close I2C device
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <sys/time.h>

#define PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;
int serial_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int setup_serial_port(const char *port) {
    serial_fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CRTSCTS;           /* disable hardware flow control */
    tty.c_cflag |= CS8;                /* 8-bit characters */
    tty.c_cflag &= ~PARENB;             /* no parity bit */
    tty.c_cflag &= ~CSTOPB;             /* only need 1 stop bit */
    tty.c_cflag &= ~INPCK;              /* ignore parity errors */
    tty.c_cflag &= ~IXON;              /* disable software flow control */
    tty.c_cflag |= IXOFF;              /* enable hardware flow control */
    tty.c_cflag &= ~ISIG;               /* disable SIGIO */

    tty.c_lflag &= ~ICANON;             /* disable canonical mode */
    tty.c_lflag &= ~ECHO;               /* disable echo */
    tty.c_lflag &= ~ECHOE;              /* disable erasure */
    tty.c_lflag &= ~ECHONL;             /* disable new-line echo */
    tty.c_lflag &= ~ISIG;               /* disable SIGINT, SIGQUIT */

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); /* shut off xon/xoff ctrl */
    tty.c_iflag &= ~(IGNBRK|BRKINT|PARMRK|ISTRIP|INLCR|IGNCR|ICRNL);

    tty.c_oflag &= ~OPOST;              /* make raw output */
    tty.c_oflag &= ~ONLCR;             /* prevent conversion of newline to carriage return/line feed */

    tty.c_cc[VMIN] = 0;                  /* read doesn't block */
    tty.c_cc[VTIME] = 5;                 /* 0.5 seconds read timeout */

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    return serial_fd;
}

int read_serial_port(int fd) {
    fd_set readfds;
    struct timeval timeout;
    char buffer[256];
    int bytes_read;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 0;
    timeout.tv_usec = TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("Error in select");
        return -1;
    } else if (select_result == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            return bytes_read;
        } else if (bytes_read == -1) {
            perror("Error reading from serial port");
            return -1;
        } else {
            // No data available
            return 0;
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_serial_port(PORT) == -1) {
        fprintf(stderr, "Failed to setup serial port. Exiting.\n");
        return 1;
    }

    printf("Serial port setup complete. Reading data...\n");

    while (program_running) {
        int bytes_read = read_serial_port(serial_fd);
        if (bytes_read > 0) {
            printf("Received: %s", (char *)malloc(bytes_read + 1));
            printf("%s\n", (char *)malloc(bytes_read + 1));
            free((char *)malloc(bytes_read + 1));
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Retrying...\n");
            sleep(1); // Wait before retrying
        }
        usleep(100000); // 0.1 seconds
    }

    if (serial_fd != -1) {
        close(serial_fd);
    }

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout for echo pulse in microseconds (50ms)
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long get_pulse_duration() {
    long start_tick, end_tick, pulse_duration;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;
    if (pulse_duration < 0) {
        pulse_duration += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_duration;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate an error
    }
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to validate the distance reading
int validate_reading(float distance) {
    if (distance < 0.0 || distance > MAX_DISTANCE) {
        return 0; // Invalid reading
    }
    return 1; // Valid reading
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("HC-SR04 Distance Sensor Program\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_duration = get_pulse_duration();

        if (pulse_duration > 0) {
            float distance = calculate_distance(pulse_duration);
            if (validate_reading(distance) == 1) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                printf("Invalid distance reading\n");
            }
        } else {
            printf("Timeout waiting for echo\n");
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define POLL_INTERVAL_NS 1000000 // 1 millisecond

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time = {0, POLL_INTERVAL_NS};
    int state = 0; // 0 for LOW, 1 for HIGH

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO state
        if (gpiod_line_set_value(line, state) < 0) {
            perror("gpiod_line_set_value");
            break; // Exit loop on error
        }

        // Report state
        printf("GPIO %d: %d\n", GPIO_PIN, state);

        // Sleep
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break; // Exit loop on error
        }
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
    }

    printf("Exiting cleanly.\n");
    return 0;
}

