#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define GPIO_27 27

// Structure to hold GPIO information
typedef struct {
    int pin;
    char *chip_name;
    struct gpiod_line *line;
} gpio_t;

// Array of GPIO pins
gpio_t gpios[] = {
    {GPIO_4, "gpiochip0", NULL},
    {GPIO_17, "gpiochip0", NULL},
    {GPIO_18, "gpiochip0", NULL},
    {GPIO_22, "gpiochip0", NULL},
    {GPIO_23, "gpiochip0", NULL},
    {GPIO_24, "gpiochip0", NULL},
    {GPIO_25, "gpiochip0", NULL},
    {GPIO_27, "gpiochip0", NULL}
};

const int num_gpios = sizeof(gpios) / sizeof(gpios[0]);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize a GPIO line
int gpio_init(gpio_t *gpio) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(gpio->chip_name);
    if (!chip) {
        fprintf(stderr, "Error: Could not open chip %s\n", gpio->chip_name);
        return -1;
    }

    gpio->line = gpiod_chip_get_line(chip, gpio->pin);
    if (!gpio->line) {
        fprintf(stderr, "Error: Could not get line %d on chip %s\n", gpio->pin, gpio->chip_name);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio->line, "gpio_control", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d as output on chip %s\n", gpio->pin, gpio->chip_name);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO line
int gpio_set_state(gpio_t *gpio, int state) {
    if (gpiod_line_set_value(gpio->line, state) < 0) {
        fprintf(stderr, "Error: Could not set value of line %d to %d\n", gpio->pin, state);
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO resources
void gpio_cleanup(gpio_t *gpio) {
    if (gpio->line) {
        gpiod_line_release(gpio->line);
    }
    if (gpio->chip_name) {
        gpiod_chip_close(gpiod_chip_open_by_name(gpio->chip_name));
    }
}

int main() {
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize GPIO pins
    for (int i = 0; i < num_gpios; i++) {
        if (gpio_init(&gpios[i]) < 0) {
            fprintf(stderr, "Error initializing GPIO %d, exiting\n", gpios[i].pin);
            // Cleanup already initialized GPIOs
            for (int j = 0; j < i; j++) {
                gpio_cleanup(&gpios[j]);
            }
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < num_gpios; i++) {
            int state = gpiod_line_get_value(gpios[i].line);
            if (state < 0) {
                fprintf(stderr, "Error reading GPIO %d, exiting\n", gpios[i].pin);
                program_running = 0; // Exit loop on error
                break;
            }
            printf("GPIO %d: %s\n", gpios[i].pin, state ? "ON" : "OFF");
        }
        sleep(0.05);
    }

    // Cleanup GPIO resources
    for (int i = 0; i < num_gpios; i++) {
        gpio_cleanup(&gpios[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Global variables for GPIO lines
struct gpiod_line *line4 = NULL;
struct gpiod_line *line17 = NULL;
struct gpiod_line *line27 = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        cleanup_gpio();
        exit(0);
    }
}

// Function to export a GPIO pin
int gpio_export(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "gpio_control", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request(line, direction, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return value;
}

// Function to clean up GPIO lines and chip
void cleanup_gpio(void) {
    if (line4) {
        gpiod_line_release(line4);
    }
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Export GPIO pins
    if (gpio_export(GPIO_4) < 0) return 1;
    if (gpio_export(GPIO_17) < 0) return 1;
    if (gpio_export(GPIO_27) < 0) return 1;

    // Set GPIO directions to output
    if (gpio_set_direction(GPIO_4, "out") < 0) return 1;
    if (gpio_set_direction(GPIO_17, "out") < 0) return 1;
    if (gpio_set_direction(GPIO_27, "out") < 0) return 1;

    // Main loop
    while (1) {
        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Print the current time and GPIO states
        printf("[%s] GPIO 4: %d, GPIO 17: %d, GPIO 27: %d\n", asctime(timeinfo), gpio_get_value(GPIO_4), gpio_get_value(GPIO_17), gpio_get_value(GPIO_27));

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    return 0;
}

