#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 16
#define PWM_FREQUENCY 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int result;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 16 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    result = gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Set PWM duty cycle (0-1000000)
        gpioPWM(PWM_GPIO, 500000); // 50% duty cycle

        // Print the current state to stdout
        printf("PWM GPIO %d set to 50%%\n", PWM_GPIO);

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable Register Values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ENABLE_AIEN 0x10

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS 0xFF // 2.4ms - 1ms

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from an I2C register
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Check device ID
    uint8_t id;
    if (i2c_read_byte(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and ALS
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) {
        fprintf(stderr, "Error enabling sensor\n");
        return -1;
    }

    // Set integration time (2.4ms)
    if (i2c_write_byte(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS) != 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    return 0;
}

// Function to read a single measurement from the TCS34725 sensor
int tcs34725_read_measurement(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[8];

    // Read all 8 bytes at once
    if (write(fd, (uint8_t[]){TCS34725_CDATA, TCS34725_RDATA, TCS34725_GDATA, TCS34725_BDATA}, 4) != 4) {
        perror("Failed to write register addresses for reading");
        return -1;
    }

    if (read(fd, data, 8) != 8) {
        perror("Failed to read measurement data");
        return -1;
    }

    *clear = (uint16_t)data[1] << 8 | data[0];
    *red = (uint16_t)data[3] << 8 | data[2];
    *green = (uint16_t)data[5] << 8 | data[4];
    *blue = (uint16_t)data[7] << 8 | data[6];

    return 0;
}

int main() {
    int fd;
    uint16_t clear, red, green, blue;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (tcs34725_read_measurement(fd, &clear, &red, &green, &blue) == 0) {
            printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read measurement\n");
        }
        sleep(0.5);
    }

    // Close I2C device (this part will not be reached in the infinite loop)
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_18 18
#define GPIO_23 23

struct gpiod_chip *chip;
struct gpiod_line *line_18, *line_23;
volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 0.01 seconds

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get line handles for GPIO 18 and GPIO 23
    line_18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_18);
        gpiod_chip_close(chip);
        return 1;
    }

    line_23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line_23) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_23);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_18, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", GPIO_18);
        gpiod_line_release(line_18);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_23, "digital_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d for output\n", GPIO_23);
        gpiod_line_release(line_18);
        gpiod_line_release(line_23);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 18 to HIGH
        if (gpiod_line_set_value(line_18, 1) < 0) {
            fprintf(stderr, "Error: Could not set value for line %d\n", GPIO_18);
            break;
        }

        // Set GPIO 23 to LOW
        if (gpiod_line_set_value(line_23, 0) < 0) {
            fprintf(stderr, "Error: Could not set value for line %d\n", GPIO_23);
            break;
        }

        // Print current state
        printf("GPIO 18: HIGH, GPIO 23: LOW\n");

        // Sleep for 0.01 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines
    gpiod_line_release(line_18);
    gpiod_line_release(line_23);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

