        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines for output
    if (gpiod_line_request_output(line_18, "digital_output", 0) < 0) {
        perror("Error requesting GPIO 18 as output");
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line_22, "digital_output", 0) < 0) {
        perror("Error requesting GPIO 22 as output");
        gpiod_line_release(line_18);
        gpiod_line_release(line_22);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Set GPIO 18 to HIGH
        if (gpiod_line_set_value(line_18, 1) < 0) {
            perror("Error setting GPIO 18 value");
            break;
