#define PORT "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define BUFFER_SIZE 256

int serial_fd = -1; // Global file descriptor for serial port
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize the serial port
int init_serial_port(const char *port) {
    serial_fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    // Configure the serial port
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read data from the serial port
int read_serial_port(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // No data available
        } else {
            perror("Error reading from serial port");
            return -1;
        }
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    }
}

// Function to process the received data
void process_data(const char *data) {
    printf("Received: %s\n", data);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize the serial port
    if (init_serial_port(PORT) == -1) {
        fprintf(stderr, "Failed to initialize serial port. Exiting.\n");
        return 1;
    }

    char buffer[BUFFER_SIZE];
    struct timeval start_time, current_time;
    double elapsed_time;
    int bytes_read;

    printf("Serial communication started. Press Ctrl+C to exit.\n");

    while (program_running) {
        bytes_read = read_serial_port(serial_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            process_data(buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from serial port. Retrying...\n");
            // Attempt to re-initialize the serial port
            close(serial_fd);
            serial_fd = -1;
            if (init_serial_port(PORT) == -1) {
                fprintf(stderr, "Failed to re-initialize serial port. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }

        gettimeofday(&current_time, NULL);
        elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_usec - start_time.tv_usec) / 1000000.0;

        if (elapsed_time >= 0.1) {
            gettimeofday(&start_time, NULL);
        }
    }

    // Close the serial port
    if (serial_fd != -1) {
        close(serial_fd);
    }

    printf("Serial communication stopped.\n");
    return 0;
}

