#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines
struct gpiod_line *line_18 = NULL;
struct gpiod_line *line_23 = NULL;
struct gpiod_line *line_24 = NULL;

// Global variable for the chip
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line_18) {
        gpiod_line_release(line_18);
    }
    if (line_23) {
        gpiod_line_release(line_23);
    }
    if (line_24) {
        gpiod_line_release(line_24);
    }

    // Release chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio()
{
    struct gpiod_chip *chip_local = NULL;
    struct gpiod_line *line_18_local = NULL;
    struct gpiod_line *line_23_local = NULL;
    struct gpiod_line *line_24_local = NULL;

    // Open the GPIO chip
    chip_local = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip_local) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", CHIP_NAME);
        return -1;
    }
    chip = chip_local;

    // Get line 18
    line_18_local = gpiod_chip_get_line(chip, GPIO_18);
    if (!line_18_local) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_18);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line 23
    line_23_local = gpiod_chip_get_line(chip, GPIO_23);
    if (!line_23_local) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_23);
        gpiod_line_release(line_18_local);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line 24
    line_24_local = gpiod_chip_get_line(chip, GPIO_24);
    if (!line_24_local) {
        fprintf(stderr, "Error: Could not get line %d\n", GPIO_24);
        gpiod_line_release(line_18_local);
        gpiod_line_release(line_23_local);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line 18 as output
    if (gpiod_line_request_output(line_18_local, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_18);
        gpiod_line_release(line_18_local);
        gpiod_line_release(line_23_local);
        gpiod_line_release(line_24_local);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line 23 as output
    if (gpiod_line_request_output(line_23_local, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_23);
        gpiod_line_release(line_18_local);
        gpiod_line_release(line_23_local);
        gpiod_line_release(line_24_local);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request line 24 as output
    if (gpiod_line_request_output(line_24_local, "gpio_output", 0) < 0) {
        fprintf(stderr, "Error: Could not request line %d as output\n", GPIO_24);
        gpiod_line_release(line_18_local);
        gpiod_line_release(line_23_local);
        gpiod_line_release(line_24_local);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO state
void set_gpio_state(int gpio, int state)
{
    if (gpio == GPIO_18) {
        gpiod_line_set_value(line_18, state);
    } else if (gpio == GPIO_23) {
        gpiod_line_set_value(line_23, state);
    } else if (gpio == GPIO_24) {
        gpiod_line_set_value(line_24, state);
    }
}

// Function to report GPIO state
void report_gpio_state()
{
    int state_18, state_23, state_24;

    // Read GPIO 18
    state_18 = gpiod_line_get_value(line_18);
    if (state_18 < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", GPIO_18);
        state_18 = -1; // Indicate error
    }

    // Read GPIO 23
    state_23 = gpiod_line_get_value(line_23);
    if (state_23 < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", GPIO_23);
        state_23 = -1; // Indicate error
    }

    // Read GPIO 24
    state_24 = gpiod_line_get_value(line_24);
    if (state_24 < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", GPIO_24);
        state_24 = -1; // Indicate error
    }

    // Print the state
    printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n", GPIO_18, state_18, GPIO_23, state_23, GPIO_24, state_24);
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO state
        set_gpio_state(GPIO_18, 1);
        set_gpio_state(GPIO_23, 0);
        set_gpio_state(GPIO_24, 1);
        sleep(1);

        // Set GPIO state
        set_gpio_state(GPIO_18, 0);
        set_gpio_state(GPIO_23, 1);
        set_gpio_state(GPIO_24, 0);
        sleep(1);

        // Report GPIO state
        report_gpio_state();
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1 0x6B

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from an I2C register
int i2c_read_word(int fd, uint8_t reg, int16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main() {
    int fd;
    int16_t accel_x, accel_y, accel_z;
    int16_t temp;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Wake up the MPU6050
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0) < 0) {
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        if (i2c_read_word(fd, MPU6050_ACCEL_XOUT_H, &accel_x) < 0) {
            close(fd);
            return 1;
        }
        if (i2c_read_word(fd, MPU6050_ACCEL_XOUT_H + 2, &accel_y) < 0) {
            close(fd);
            return 1;
        }
        if (i2c_read_word(fd, MPU6050_ACCEL_XOUT_H + 4, &accel_z) < 0) {
            close(fd);
            return 1;
        }

        // Print the data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define POLL_INTERVAL_MS 600

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000; // Convert milliseconds to nanoseconds

    // Register signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "digital_output";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Set GPIO pin to HIGH
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (HIGH)");
            break;
        }

        // Print HIGH
        printf("HIGH\n");

        // Set GPIO pin to LOW
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value (LOW)");
            break;
        }

        // Print LOW
        printf("LOW\n");

        // Sleep for POLL_INTERVAL_MS
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    if (gpiod_line_release(line) < 0) {
        perror("gpiod_line_release");
    }

    // Close GPIO chip
    if (gpiod_chip_close(chip) < 0) {
        perror("gpiod_chip_close");
    }

    printf("Exiting cleanly.\n");
    return 0;
}
